HQ.reg("extra","grammar",[{"id":"alphabet","title":"Алфавит и огласовки","level":"A1","text":["В иврите 22 буквы, и все они согласные. Пишут справа налево, заглавных букв нет.","Пять букв в конце слова пишутся иначе (конечные формы): כ → ך, מ → ם, נ → ן, פ → ף, צ → ץ. Например: ארץ (страна), שלום (мир).","Гласные обычно не пишут. Их обозначают огласовки (никуд) — точки и чёрточки под и над буквами. Огласовки есть в детских книгах, словарях и учебниках, а в газетах, на вывесках и в телефоне их нет.","Чтобы текст без огласовок читался легче, буквы ו и י часто служат гласными: ו = «о» или «у», י = «и» (полное написание): שלום — шало́м, תלמיד — талми́д.","Некоторые буквы звучат по-разному: בּ = б, ב = в; כּ = к, כ = х; פּ = п, פ = ф. Точка внутри (дагеш) даёт твёрдый звук. Буквы א и ע в современном произношении почти не слышны."],"table":{"head":["Знак","Звук","Пример"],"rows":[["בַ / בָ (патах, камац)","а","דָּג — даг (рыба)"],["בֶ / בֵ (сеголь, цере)","э","בֵּן — бен (сын)"],["בִ / בִי (хирик)","и","מִי — ми (кто)"],["בֹ / בוֹ (холам)","о","טוֹב — тов (хороший)"],["בֻ / בוּ (кубуц, шурук)","у","הוּא — hу (он)"],["בְ (шва)","краткое «э» или ничего","בְּבַקָּשָׁה — бевакаша́"]]},"examples":[{"he":"שלום","nq":"שָׁלוֹם","tr":"шало́м","ru":"здравствуйте; мир"},{"he":"אבא","nq":"אַבָּא","tr":"а́ба","ru":"папа"},{"he":"אמא","nq":"אִמָּא","tr":"и́ма","ru":"мама"},{"he":"ספר","nq":"סֵפֶר","tr":"се́фер","ru":"книга"},{"he":"כלב","nq":"כֶּלֶב","tr":"ке́лев","ru":"собака"},{"he":"בית","nq":"בַּיִת","tr":"ба́йит","ru":"дом"},{"he":"חלון","nq":"חַלּוֹן","tr":"хало́н","ru":"окно"},{"he":"ארץ","nq":"אֶרֶץ","tr":"э́рец","ru":"страна, земля"}],"quiz":[{"q":"В какую сторону пишут на иврите?","opts":["сверху вниз","в любую сторону","справа налево","слева направо"],"a":2,"why":"Иврит пишут и читают справа налево."},{"q":"Какая буква — конечная форма מ?","opts":["ם","ס","ן","ך"],"a":0,"why":"מ в конце слова пишется как ם: שלום."},{"q":"Конечная форма буквы נ:","opts":["ץ","ן","ף","ך"],"a":1,"why":"נ в конце слова → ן: בן."},{"q":"Как читается בּ (с точкой внутри)?","opts":["п","ф","б","в"],"a":2,"why":"Дагеш даёт твёрдый звук: בּ = б, ב без точки = в."},{"q":"Как читается כ без точки (как в слове מכתב — михта́в)?","opts":["х","к","ш","ц"],"a":0,"why":"כ без дагеша звучит как «х», с дагешем (כּ) — как «к»."},{"q":"Какая буква в полном написании чаще всего обозначает звук «и»?","opts":["א","י","ה","ו"],"a":1,"why":"י служит гласной «и»: תלמיד — талми́д."},{"q":"Буква ו в слове טוב читается как…","opts":["в","у","о","и"],"a":2,"why":"טוב — тов: ו здесь гласная «о»."},{"q":"Как пишется «шалом» без огласовок?","opts":["סלום","שלומ","שלום","שאלום"],"a":2,"why":"Полное написание с ו для «о» и конечной ם."}]},{"id":"gender","title":"Род: мужской и женский","level":"A1","text":["Каждое существительное в иврите — мужского или женского рода. Среднего рода нет. От рода зависят прилагательные, глаголы и числительные.","Женский род обычно видно по окончанию: ударное ־ה (ילדה — ялда́) или ־ת (דלת, מחברת). Слова без этих окончаний чаще всего мужского рода: ילד, בית, ספר.","Есть исключения, их надо запомнить: עיר (город), ארץ (страна), יד (рука), רגל (нога), עין (глаз) — женского рода без окончания. А לילה (ночь) — мужского рода, хотя кончается на ־ה.","Род часто не совпадает с русским: ספר (книга) — мужской, שולחן (стол) — мужской, דלת (дверь) — женский.","Женский род людей и профессий образуется окончанием ־ה, ־ת или ־ית: תלמיד → תלמידה, מהנדס → מהנדסת, סטודנט → סטודנטית."],"table":{"head":["Мужской","Женский","Перевод"],"rows":[["יֶלֶד","יַלְדָּה","мальчик / девочка"],["תַּלְמִיד","תַּלְמִידָה","ученик / ученица"],["חָבֵר","חֲבֵרָה","друг / подруга"],["דּוֹד","דּוֹדָה","дядя / тётя"],["רוֹפֵא","רוֹפְאָה","врач"],["מְהַנְדֵּס","מְהַנְדֶּסֶת","инженер"],["סְטוּדֶנְט","סְטוּדֶנְטִית","студент / студентка"]]},"examples":[{"he":"ילד","nq":"יֶלֶד","tr":"е́лед","ru":"мальчик (м.р.)"},{"he":"ילדה","nq":"יַלְדָּה","tr":"ялда́","ru":"девочка (ж.р.)"},{"he":"מחברת","nq":"מַחְבֶּרֶת","tr":"махбе́рет","ru":"тетрадь (ж.р.)"},{"he":"שולחן","nq":"שֻׁלְחָן","tr":"шульха́н","ru":"стол (м.р.)"},{"he":"עיר","nq":"עִיר","tr":"ир","ru":"город (ж.р.)"},{"he":"לילה","nq":"לַיְלָה","tr":"ла́йла","ru":"ночь (м.р.)"},{"he":"דלת","nq":"דֶּלֶת","tr":"де́лет","ru":"дверь (ж.р.)"},{"he":"מהנדסת","nq":"מְהַנְדֶּסֶת","tr":"меhанде́сет","ru":"инженер (ж)"}],"quiz":[{"q":"Какого рода слово ילדה?","opts":["мужского","женского","обоих родов","среднего"],"a":1,"why":"Окончание ־ה → женский род."},{"q":"Какого рода слово ספר (книга)?","opts":["зависит от контекста","женского","мужского","среднего"],"a":2,"why":"Нет окончания ־ה/־ת → мужской род, хотя по-русски «книга» — женского."},{"q":"Какое слово женского рода?","opts":["דלת","שולחן","ספר","לילה"],"a":0,"why":"דלת кончается на ־ת → женский род."},{"q":"Какое слово мужского рода, несмотря на окончание ־ה?","opts":["לילה","ילדה","חברה","דודה"],"a":0,"why":"לילה (ночь) — исключение: мужской род."},{"q":"Женский род от תלמיד (ученик):","opts":["תלמידות","תלמידה","תלמידים","תלמידית"],"a":1,"why":"תלמיד + ־ה = תלמידה."},{"q":"Женский род от סטודנט:","opts":["סטודנטית","סטודנטה","סטודנטים","סטודנטות"],"a":0,"why":"Заимствованные слова часто берут ־ית: סטודנטית."},{"q":"Какого рода слово עיר (город)?","opts":["мужского","женского","среднего","обоих родов"],"a":1,"why":"עיר — женский род без окончания, это надо запомнить."},{"q":"Женский род от מהנדס (инженер):","opts":["מהנדסה","מהנדסית","מהנדסת","מהנדסות"],"a":2,"why":"מהנדס → מהנדסת (меhанде́сет)."}]},{"id":"plural","title":"Множественное число","level":"A1","text":["Мужской род во множественном числе обычно получает окончание ־ים (-им): תלמיד → תלמידים, ילד → ילדים.","Женский род — окончание ־ות (-от). Окончание ־ה отпадает: ילדה → ילדות, מורה → מורות. ־ת тоже заменяется: מחברת → מחברות, סטודנטית → סטודנטיות.","Внутри слова гласные часто меняются: ילד (е́лед) → ילדים (йелади́м), ספר (се́фер) → ספרים (сфари́м). Это нормально — привыкнете на слух.","Исключения: некоторые слова мужского рода берут ־ות: שולחן → שולחנות, מקום → מקומות, לילה → לילות. Некоторые женского — ־ים: מילה → מילים, שנה → שנים. Род при этом не меняется: שולחנות גדולים (большие столы).","Особые формы: איש → אנשים, אישה → נשים, בית → בתים, עיר → ערים. Парные предметы и части тела получают ־יים: ידיים (руки), עיניים (глаза), נעליים (туфли)."],"table":{"head":["Ед. число","Мн. число","Перевод"],"rows":[["יֶלֶד","יְלָדִים","мальчик — дети"],["יַלְדָּה","יְלָדוֹת","девочка — девочки"],["שֻׁלְחָן","שֻׁלְחָנוֹת","стол (м.р., но ־ות)"],["מָקוֹם","מְקוֹמוֹת","место (м.р., но ־ות)"],["מִלָּה","מִלִּים","слово (ж.р., но ־ים)"],["שָׁנָה","שָׁנִים","год (ж.р., но ־ים)"],["אִישׁ / אִשָּׁה","אֲנָשִׁים / נָשִׁים","мужчина / женщина"],["בַּיִת","בָּתִּים","дом"]]},"examples":[{"he":"ילדים","nq":"יְלָדִים","tr":"йелади́м","ru":"дети, мальчики"},{"he":"ילדות","nq":"יְלָדוֹת","tr":"йеладо́т","ru":"девочки"},{"he":"ספרים","nq":"סְפָרִים","tr":"сфари́м","ru":"книги"},{"he":"מחברות","nq":"מַחְבָּרוֹת","tr":"махбаро́т","ru":"тетради"},{"he":"אנשים","nq":"אֲנָשִׁים","tr":"анаши́м","ru":"люди"},{"he":"נשים","nq":"נָשִׁים","tr":"наши́м","ru":"женщины"},{"he":"שולחנות","nq":"שֻׁלְחָנוֹת","tr":"шульхано́т","ru":"столы"},{"he":"עיניים","nq":"עֵינַיִם","tr":"эйна́им","ru":"глаза"}],"quiz":[{"q":"Множественное число от תלמיד:","opts":["תלמידים","תלמידיים","תלמידה","תלמידות"],"a":0,"why":"Мужской род → ־ים."},{"q":"Множественное число от מורה (учительница):","opts":["מוריות","מורות","מורים","מורהות"],"a":1,"why":"Женский род: ־ה отпадает, добавляется ־ות."},{"q":"Множественное число от שולחן:","opts":["שולחנות","שולחניים","שולחנים","שולחנת"],"a":0,"why":"שולחן — мужской род, но мн. число на ־ות (исключение)."},{"q":"Множественное число от מילה (слово):","opts":["מילת","מיליים","מילים","מילהות"],"a":2,"why":"מילה — женский род, но мн. число на ־ים (исключение)."},{"q":"Множественное число от אישה (женщина):","opts":["אנשים","אישיות","אישהות","נשים"],"a":3,"why":"Особая форма: אישה → נשים. אנשים — это «люди»."},{"q":"Как сказать «большие столы»?","opts":["שולחנות גדולות","שולחן גדולים","שולחנים גדולים","שולחנות גדולים"],"a":3,"why":"שולחן мужского рода → прилагательное на ־ים, хотя само слово на ־ות."},{"q":"Множественное число от בית:","opts":["ביתות","ביתים","בתים","בתות"],"a":2,"why":"Особая форма: בית → בתים (бати́м)."},{"q":"Как сказать «руки» (парное)?","opts":["ידיות","ידיים","ידות","יידים"],"a":1,"why":"Парные части тела → ־יים: ידיים (яда́им)."}]},{"id":"article","title":"Артикль ה и его «прилипание»","level":"A1","text":["Определённый артикль — ה (hа-). Он пишется слитно со словом: ילד — мальчик (какой-то), הילד — мальчик (тот самый, известный). Неопределённого артикля нет.","В русском артиклей нет, поэтому его часто забывают. Ставьте ה, когда предмет уже знаком, единственный в своём роде или уточнён: השמש (солнце), הבית שלי (мой дом).","Артикль «прилипает» к предлогам ב, ל, כ: буква ה исчезает, а её звук «а» переходит к предлогу. ב + הבית = בבית (баба́йит — в доме), ל + הים = לים (лая́м — к морю). На письме без огласовок разницы не видно, только на слух: бе-ба́йит — «в каком-то доме», ба-ба́йит — «в доме (этом), дома».","С מ и ש артикль сохраняется: מהבית (меhаба́йит — из дома).","Имена собственные и слова с притяжательным суффиксом артикля не получают: ירושלים, ביתי (мой дом)."],"table":{"head":["Без артикля","С артиклем","С предлогом"],"rows":[["בַּיִת — дом","הַבַּיִת","בַּבַּיִת — в доме"],["חֶדֶר — комната","הַחֶדֶר","לַחֶדֶר — в комнату"],["עִיר — город","הָעִיר","בָּעִיר — в городе"],["יָם — море","הַיָּם","לַיָּם — к морю"],["בַּיִת — дом","הַבַּיִת","מֵהַבַּיִת — из дома"]]},"examples":[{"he":"הילד אוכל","nq":"הַיֶּלֶד אוֹכֵל","tr":"hае́лед охе́ль","ru":"мальчик (тот самый) ест"},{"he":"הספר על השולחן","nq":"הַסֵּפֶר עַל הַשֻּׁלְחָן","tr":"hасе́фер аль hашульха́н","ru":"книга на столе"},{"he":"אני בבית","nq":"אֲנִי בַּבַּיִת","tr":"ани́ баба́йит","ru":"я дома"},{"he":"אני הולכת לים","nq":"אֲנִי הוֹלֶכֶת לַיָּם","tr":"ани́ hоле́хет лая́м","ru":"я иду к морю (ж)"},{"he":"מהעיר","nq":"מֵהָעִיר","tr":"меhаи́р","ru":"из города"},{"he":"השמש חמה","nq":"הַשֶּׁמֶשׁ חַמָּה","tr":"hаше́меш хама́","ru":"солнце жаркое"},{"he":"בעיר","nq":"בָּעִיר","tr":"баи́р","ru":"в городе"}],"quiz":[{"q":"Как сказать «мальчик» (известный, тот самый)?","opts":["ילד","לילד","ההילד","הילד"],"a":3,"why":"Определённость → артикль ה слитно со словом."},{"q":"ב + הבית =","opts":["בהבית","בית","הבבית","בבית"],"a":3,"why":"После ב буква ה выпадает, остаётся звук «а»: баба́йит."},{"q":"ל + העיר =","opts":["להעיר","לעירה","לעיר","הלעיר"],"a":2,"why":"После ל буква ה выпадает: лаи́р."},{"q":"מ + הבית =","opts":["מבית","ממבית","בהבית","מהבית"],"a":3,"why":"С מ артикль сохраняется: מהבית (меhаба́йит)."},{"q":"«Книга на столе» (известная книга, известный стол):","opts":["ספר על שולחן","ספר על השולחן","הספר על שולחן","הספר על השולחן"],"a":3,"why":"Оба предмета известны → ה перед обоими."},{"q":"Нужен ли артикль перед ירושלים?","opts":["нет","только после ב","да","только в начале предложения"],"a":0,"why":"Имена собственные не получают артикль."},{"q":"Как прочитать בבית в значении «дома, в (этом) доме»?","opts":["беhаба́йит","бба́йит","бэба́йит","баба́йит"],"a":3,"why":"ב + ה → ба-: баба́йит."}]},{"id":"adjectives","title":"Прилагательные и согласование","level":"A1","text":["Прилагательное стоит ПОСЛЕ существительного: ילד טוב — хороший мальчик (буквально «мальчик хороший»).","Оно согласуется в роде и числе, поэтому у него 4 формы: טוב, טובה, טובים, טובות. Окончания те же, что у существительных.","Прилагательное смотрит на род слова, а не на окончание: שולחנות גדולים (столы — м.р.), מילים חדשות (слова — ж.р.).","Если у существительного есть артикль, прилагательное тоже его получает: הילד הטוב — хороший мальчик (тот). Без второго ה получается целое предложение: הילד טוב — «мальчик хороший».","Прилагательные на ־י в женском роде получают ־ית: מרכזי → מרכזית, ישראלי → ישראלית."],"table":{"head":["Род","Ед. число","Мн. число"],"rows":[["мужской","טוֹב","טוֹבִים"],["женский","טוֹבָה","טוֹבוֹת"],["мужской","גָּדוֹל","גְּדוֹלִים"],["женский","גְּדוֹלָה","גְּדוֹלוֹת"],["мужской","חָדָשׁ","חֲדָשִׁים"],["женский","חֲדָשָׁה","חֲדָשׁוֹת"],["мужской","מֶרְכָּזִי","מֶרְכָּזִיִּים"],["женский","מֶרְכָּזִית","מֶרְכָּזִיּוֹת"]]},"examples":[{"he":"ילד טוב","nq":"יֶלֶד טוֹב","tr":"е́лед тов","ru":"хороший мальчик"},{"he":"ילדה טובה","nq":"יַלְדָּה טוֹבָה","tr":"ялда́ това́","ru":"хорошая девочка"},{"he":"בית גדול","nq":"בַּיִת גָּדוֹל","tr":"ба́йит гадо́ль","ru":"большой дом"},{"he":"מילים חדשות","nq":"מִלִּים חֲדָשׁוֹת","tr":"мили́м хадашо́т","ru":"новые слова"},{"he":"הבית הגדול","nq":"הַבַּיִת הַגָּדוֹל","tr":"hаба́йит hагадо́ль","ru":"большой дом (тот самый)"},{"he":"הבית גדול","nq":"הַבַּיִת גָּדוֹל","tr":"hаба́йит гадо́ль","ru":"дом большой"},{"he":"תחנה מרכזית","nq":"תַּחֲנָה מֶרְכָּזִית","tr":"тахана́ меркази́т","ru":"центральная автостанция"}],"quiz":[{"q":"Выберите правильную форму: ילדה ___ (хорошая девочка)","opts":["טובים","טוב","טובות","טובה"],"a":3,"why":"ילדה — женский род, ед. число → טובה."},{"q":"ילדים ___ (маленькие дети)","opts":["קטנים","קטנה","קטנות","קטן"],"a":0,"why":"ילדים — м.р., мн. число → קטנים."},{"q":"מילים ___ (новые слова)","opts":["חדשים","חדשה","חדשות","חדש"],"a":2,"why":"מילה — женский род, хотя мн. число на ־ים → חדשות."},{"q":"שולחנות ___ (большие столы)","opts":["גדולים","גדול","גדולות","גדולה"],"a":0,"why":"שולחן — мужской род → גדולים."},{"q":"Как сказать «новая машина» (та самая, определённая)?","opts":["המכונית החדשה","מכונית החדשה","המכונית חדשה","החדשה מכונית"],"a":0,"why":"При определённом существительном ה стоит и у прилагательного."},{"q":"Что означает הבית גדול?","opts":["большой дом","дом небольшой","большие дома","Дом большой."],"a":3,"why":"Без ה у прилагательного это предложение: «дом (есть) большой»."},{"q":"בחורה ___ (израильская девушка)","opts":["ישראליה","ישראלי","ישראלים","ישראלית"],"a":3,"why":"Прилагательное на ־י в ж.р. → ־ית."},{"q":"Как сказать «красивый город»?","opts":["עיר יפה","יפות עיר","עיר יפים","יפה עיר"],"a":0,"why":"Прилагательное после существительного; עיר — ж.р. → יפה."}]},{"id":"pronouns","title":"Личные местоимения","level":"A1","text":["Местоимения различают род не только в «он/она», но и в «ты» и «вы»: אתה — ты (мужчине), את — ты (женщине).","«Я» и «мы» — без рода: אני, אנחנו. «Они» — две формы: הם (мужчины или смешанная группа), הן (только женщины). В разговоре часто говорят הם и אתם и о женщинах.","Вежливого «Вы» нет: к любому человеку, даже к начальнику или врачу, обращаются на «ты» — אתה или את. Это не грубо."],"table":{"head":["Местоимение","Транскрипция","Перевод"],"rows":[["אֲנִי","ани́","я"],["אַתָּה / אַתְּ","ата́ / ат","ты (м / ж)"],["הוּא / הִיא","hу / hи","он / она"],["אֲנַחְנוּ","ана́хну","мы"],["אַתֶּם / אַתֶּן","ате́м / ате́н","вы (м / ж)"],["הֵם / הֵן","hем / hен","они (м / ж)"]]},"examples":[{"he":"אני מהנדס","nq":"אֲנִי מְהַנְדֵּס","tr":"ани́ меhанде́с","ru":"я инженер (м)"},{"he":"אני מהנדסת","nq":"אֲנִי מְהַנְדֶּסֶת","tr":"ани́ меhанде́сет","ru":"я инженер (ж)"},{"he":"את מישראל?","nq":"אַתְּ מִיִּשְׂרָאֵל?","tr":"ат мийисраэ́ль?","ru":"ты (ж) из Израиля?"},{"he":"הוא רופא","nq":"הוּא רוֹפֵא","tr":"hу рофе́","ru":"он врач"},{"he":"היא מורה","nq":"הִיא מוֹרָה","tr":"hи мора́","ru":"она учительница"},{"he":"אנחנו מרוסיה","nq":"אֲנַחְנוּ מֵרוּסְיָה","tr":"ана́хну меру́сья","ru":"мы из России"},{"he":"הם עובדים","nq":"הֵם עוֹבְדִים","tr":"hем овди́м","ru":"они работают"},{"he":"אתם רעבים?","nq":"אַתֶּם רְעֵבִים?","tr":"ате́м реэви́м?","ru":"вы голодны?"}],"quiz":[{"q":"Как сказать «ты» женщине?","opts":["היא","את","אתן","אתה"],"a":1,"why":"Женщине — את (ат), мужчине — אתה (ата́)."},{"q":"«Они» о группе только из женщин:","opts":["הן","הם","אתן","היא"],"a":0,"why":"Только женщины → הן."},{"q":"Как сказать «мы»?","opts":["אתם","הם","אני","אנחנו"],"a":3,"why":"אנחנו (ана́хну) — без рода."},{"q":"Вы обращаетесь к пожилому незнакомому мужчине. Какое слово?","opts":["את","אתה","הוא","אתם"],"a":1,"why":"Вежливого «Вы» нет: одному мужчине — אתה."},{"q":"Группа: двое мужчин и женщина. «Они» =","opts":["היא","הן","הם","אתם"],"a":2,"why":"Смешанная группа → мужская форма הם."},{"q":"___ מורה (она учительница)","opts":["הם","אתה","היא","הוא"],"a":2,"why":"«Она» — היא (hи)."},{"q":"«Вы» группе женщин (по норме):","opts":["אתם","הן","אתן","את"],"a":2,"why":"Женская группа → אתן; в разговоре часто говорят אתם."}]},{"id":"present_be","title":"«Быть» в настоящем; זה / זאת / אלה","level":"A1","text":["В настоящем времени глагола «быть» нет — как и в русском: אני רופא — «я врач», הדירה קטנה — «квартира маленькая».","«Это» — זה (мужской род), זאת (женский), אלה (мн. число, оба рода): זה ספר, זאת מחברת, אלה ילדים. В разговоре вместо זאת часто говорят זו.","Не путайте «это …» и «этот …». זה ספר — это книга. А «эта книга» — הספר הזה: слово «этот» ставится после существительного, и у обоих есть ה.","В длинных предложениях связкой иногда служат הוא / היא / הם: הבעיה היא ש… — проблема в том, что…; דני הוא המנהל — Дани — начальник."],"table":{"head":["","«Это …»","«этот …»"],"rows":[["м. р.","זֶה סֵפֶר","הַסֵּפֶר הַזֶּה"],["ж. р.","זֹאת מַחְבֶּרֶת","הַמַּחְבֶּרֶת הַזֹּאת"],["мн. ч.","אֵלֶּה סְפָרִים","הַסְּפָרִים הָאֵלֶּה"]]},"examples":[{"he":"אני רופאה","nq":"אֲנִי רוֹפְאָה","tr":"ани́ рофъа́","ru":"я врач (ж)"},{"he":"הדירה קטנה","nq":"הַדִּירָה קְטַנָּה","tr":"hадира́ ктана́","ru":"квартира маленькая"},{"he":"זה הבית שלי","nq":"זֶה הַבַּיִת שֶׁלִּי","tr":"зе hаба́йит шели́","ru":"это мой дом"},{"he":"זאת אמא שלי","nq":"זֹאת אִמָּא שֶׁלִּי","tr":"зот и́ма шели́","ru":"это моя мама"},{"he":"אלה החברים שלי","nq":"אֵלֶּה הַחֲבֵרִים שֶׁלִּי","tr":"э́ле hахавери́м шели́","ru":"это мои друзья"},{"he":"הספר הזה מעניין","nq":"הַסֵּפֶר הַזֶּה מְעַנְיֵן","tr":"hасе́фер hазе́ меанье́н","ru":"эта книга интересная"},{"he":"מה זה?","nq":"מָה זֶה?","tr":"ма зе?","ru":"что это?"}],"quiz":[{"q":"___ מחברת (Это тетрадь)","opts":["אלה","הזאת","זאת","זה"],"a":2,"why":"מחברת — ж.р. → זאת."},{"q":"___ ספרים (Это книги)","opts":["האלה","אלה","זאת","זה"],"a":1,"why":"Мн. число → אלה."},{"q":"Как сказать «эта девочка»?","opts":["ילדה הזאת","הילדה זאת","הילדה הזאת","זאת ילדה"],"a":2,"why":"«Этот» — после слова, и ה у обоих: הילדה הזאת."},{"q":"Как сказать «я учитель» (м)?","opts":["אני הוא מורה","אני מורה","אני יש מורה","אני היה מורה"],"a":1,"why":"В настоящем времени связки нет."},{"q":"Что означает זה הבית שלי?","opts":["это мой дом","у меня есть дом","этот мой дом","мой дом есть"],"a":0,"why":"זה + существительное = «это …»."},{"q":"Как сказать «эти дома»?","opts":["בתים האלה","הבתים האלה","אלה בתים","הבתים הזה"],"a":1,"why":"Мн. число → האלה, и ה у существительного."},{"q":"Какое слово в разговоре часто заменяет זאת?","opts":["הזה","אלו","זו","זה"],"a":2,"why":"זו = זאת (ж.р.)."}]},{"id":"yesh_ein","title":"יש / אין и «у меня есть»","level":"A1","text":["יש — «есть, имеется», אין — «нет, не имеется». Эти слова не меняются по роду и числу: יש חלב, יש ביצים, אין זמן.","«У меня есть» = יש לי (буквально «есть мне»), «у меня нет» = אין לי. Владельца обозначает предлог ל: יש לך, יש לו, יש לה… Для имени: לדני יש מכונית — у Дани есть машина.","В прошедшем и будущем времени вместо יש употребляют глагол «быть», и он согласуется с предметом: היה לי זמן (זמן — м.р.), הייתה לי בעיה (ж.р.), היו לי שאלות (мн.); יהיה לי זמן. Отрицание: לא היה לי זמן."],"table":{"head":["Кто","«есть у …»","Перевод"],"rows":[["אני","יֵשׁ לִי","у меня есть"],["אתה / את","יֵשׁ לְךָ / יֵשׁ לָךְ","у тебя есть (м / ж)"],["הוא / היא","יֵשׁ לוֹ / יֵשׁ לָהּ","у него / у неё есть"],["אנחנו","יֵשׁ לָנוּ","у нас есть"],["אתם / אתן","יֵשׁ לָכֶם / יֵשׁ לָכֶן","у вас есть"],["הם / הן","יֵשׁ לָהֶם / יֵשׁ לָהֶן","у них есть"]]},"examples":[{"he":"יש לי שאלה","nq":"יֵשׁ לִי שְׁאֵלָה","tr":"еш ли шеэла́","ru":"у меня есть вопрос"},{"he":"אין לי זמן","nq":"אֵין לִי זְמַן","tr":"эйн ли зман","ru":"у меня нет времени"},{"he":"יש פה חנות?","nq":"יֵשׁ פֹּה חֲנוּת?","tr":"еш по хану́т?","ru":"здесь есть магазин?"},{"he":"אין חלב","nq":"אֵין חָלָב","tr":"эйн хала́в","ru":"нет молока"},{"he":"יש לך ילדים?","nq":"יֵשׁ לְךָ יְלָדִים?","tr":"еш леха́ йелади́м?","ru":"у тебя (м) есть дети?"},{"he":"הייתה לי בעיה","nq":"הָיְתָה לִי בְּעָיָה","tr":"hайта́ ли беая́","ru":"у меня была проблема"},{"he":"יהיה לנו זמן מחר","nq":"יִהְיֶה לָנוּ זְמַן מָחָר","tr":"иhье́ ла́ну зман маха́р","ru":"завтра у нас будет время"}],"quiz":[{"q":"Как сказать «у меня есть машина»?","opts":["אני יש מכונית","יש שלי מכונית","יש לי מכונית","יש אני מכונית"],"a":2,"why":"Владелец — с предлогом ל: יש לי."},{"q":"Как сказать «у неё нет времени»?","opts":["אין לו זמן","לא יש לה זמן","היא אין זמן","אין לה זמן"],"a":3,"why":"«Нет» = אין, «у неё» = לה."},{"q":"___ לי שאלות (у меня были вопросы)","opts":["היה","היו","יש","הייתה"],"a":1,"why":"Прошедшее, предмет во мн. числе → היו."},{"q":"___ לי בעיה (у меня была проблема)","opts":["היה","תהיה","היו","הייתה"],"a":3,"why":"בעיה — ж.р. → הייתה."},{"q":"Меняется ли יש по роду и числу?","opts":["да, в женском роде","только в вопросах","нет, никогда","только во мн. числе"],"a":2,"why":"יש и אין не изменяются."},{"q":"Как сказать «у нас есть»?","opts":["יש לכם","יש לנו","יש להם","יש אנחנו"],"a":1,"why":"«Нам» = לנו."},{"q":"Как сказать «у Дани есть собака»?","opts":["של דני יש כלב","לדני יש כלב","דני יש כלב","יש דני כלב"],"a":1,"why":"Владелец с ל: לדני."}]},{"id":"questions","title":"Вопросы и порядок слов","level":"A1","text":["Вопрос «да или нет» обычно отличается от утверждения только интонацией: אתה מדבר עברית. — Ты говоришь на иврите. אתה מדבר עברית? — Ты говоришь на иврите? В книжном языке в начале ставят האם.","Вопросительное слово ставится в начало: מה (что), מי (кто), איפה (где), לאן (куда), מאיפה (откуда), מתי (когда), למה (почему), איך (как), כמה (сколько), איזה / איזו / אילו (какой / какая / какие).","Предлог стоит перед вопросительным словом, как в русском: עם מי? (с кем?), על מה? (о чём?), של מי? (чей?).","Обычный порядок слов — как в русском: подлежащее — сказуемое — дополнение: דני קונה לחם. После вопросительного слова глагол может стоять раньше подлежащего: מה אומר הרופא? = מה הרופא אומר?"],"table":{"head":["Слово","Транскрипция","Перевод"],"rows":[["מָה","ма","что"],["מִי","ми","кто"],["אֵיפֹה / לְאָן / מֵאֵיפֹה","э́йфо / леа́н / меэ́йфо","где / куда / откуда"],["מָתַי","мата́й","когда"],["לָמָּה","ла́ма","почему, зачем"],["אֵיךְ","эйх","как"],["כַּמָּה","ка́ма","сколько"],["אֵיזֶה / אֵיזוֹ / אֵילוּ","э́йзе / э́йзо / э́йлу","какой / какая / какие"]]},"examples":[{"he":"איפה התחנה?","nq":"אֵיפֹה הַתַּחֲנָה?","tr":"э́йфо hатахана́?","ru":"где остановка?"},{"he":"לאן את נוסעת?","nq":"לְאָן אַתְּ נוֹסַעַת?","tr":"леа́н ат носа́ат?","ru":"куда ты (ж) едешь?"},{"he":"מאיפה אתה?","nq":"מֵאֵיפֹה אַתָּה?","tr":"меэ́йфо ата́?","ru":"откуда ты (м)?"},{"he":"עם מי אתה גר?","nq":"עִם מִי אַתָּה גָּר?","tr":"им ми ата́ гар?","ru":"с кем ты (м) живёшь?"},{"he":"איזה אוטובוס נוסע לים?","nq":"אֵיזֶה אוֹטוֹבּוּס נוֹסֵעַ לַיָּם?","tr":"э́йзе о́тобус носе́а лая́м?","ru":"какой автобус идёт к морю?"},{"he":"למה אתה עצוב?","nq":"לָמָּה אַתָּה עָצוּב?","tr":"ла́ма ата́ ацу́в?","ru":"почему ты (м) грустный?"},{"he":"מתי הפגישה?","nq":"מָתַי הַפְּגִישָׁה?","tr":"мата́й hапгиша́?","ru":"когда встреча?"},{"he":"של מי התיק הזה?","nq":"שֶׁל מִי הַתִּיק הַזֶּה?","tr":"шель ми hати́к hазе́?","ru":"чья это сумка?"}],"quiz":[{"q":"«Куда ты едешь?» (мужчине)","opts":["לאן אתה נוסע?","מאיפה אתה נוסע?","מתי אתה נוסע?","איפה אתה נוסע?"],"a":0,"why":"Направление → לאן (куда)."},{"q":"«С кем?»","opts":["את מי?","עם מי?","עם מה?","מי עם?"],"a":1,"why":"Предлог стоит перед вопросительным словом: עם מי."},{"q":"По норме: «какая квартира?» (דירה — ж.р.)","opts":["מה דירה?","איזה דירה?","איזו דירה?","אילו דירה?"],"a":2,"why":"Женский род → איזו; в разговоре часто говорят איזה."},{"q":"«Откуда вы?»","opts":["איפה אתם?","מאיפה אתם?","לאן אתם?","מתי אתם?"],"a":1,"why":"«Откуда» = מאיפה."},{"q":"Как превратить אתה רעב в вопрос «Ты голоден?»","opts":["поднять интонацию: אתה רעב?","добавить מה в конце","поменять слова: רעב אתה","добавить לא"],"a":0,"why":"Вопрос «да/нет» делается интонацией."},{"q":"«О чём ты думаешь?» (мужчине)","opts":["על מה אתה חושב?","מה אתה חושב?","מה על אתה חושב?","מה אתה חושב על?"],"a":0,"why":"Предлог перед вопросительным словом: על מה."},{"q":"«Чья это книга?»","opts":["של מי הספר הזה?","מי הספר הזה?","מי של הספר?","של מה הספר הזה?"],"a":0,"why":"«Чей» = של מי."},{"q":"«Почему?»","opts":["מה?","למה?","כמה?","מתי?"],"a":1,"why":"למה (ла́ма) — почему, зачем."}]},{"id":"negation","title":"Отрицание: לא, אין, אל","level":"A1","text":["לא — «не» перед глаголом, прилагательным и другими словами, а также «нет» в ответе: אני לא יודע — я не знаю; זה לא טוב — это нехорошо.","אין — «нет, не имеется» (противоположность יש): אין חלב, אין לי זמן. В книжном стиле אין с окончаниями отрицает настоящее время: אינני יודע, הוא אינו בבית. В разговоре в этих случаях говорят просто לא.","אל — запрет («не делай!»), всегда с формой будущего времени: אל תדאג — не волнуйся, אל תיגע — не трогай. С просьбой-запретом לא не используют.","Двойное отрицание, как в русском, — норма: אף אחד לא בא — никто не пришёл; לא קרה כלום — ничего не случилось; הוא אף פעם לא מאחר — он никогда не опаздывает."],"table":{"head":["Слово","Когда","Пример"],"rows":[["לֹא","«не» перед глаголом, прилагательным","אֲנִי לֹא יוֹדֵעַ"],["אֵין","«нет, не имеется»","אֵין זְמַן"],["אַל","запрет + будущее время","אַל תִּדְאַג"],["אַף אֶחָד לֹא","никто не","אַף אֶחָד לֹא בָּא"],["כְּלוּם / שׁוּם דָּבָר","ничего","לֹא קָרָה כְּלוּם"],["אַף פַּעַם לֹא","никогда не","הוּא אַף פַּעַם לֹא מְאַחֵר"]]},"examples":[{"he":"אני לא יודעת","nq":"אֲנִי לֹא יוֹדַעַת","tr":"ани́ ло йода́ат","ru":"я не знаю (ж)"},{"he":"אין בעיה","nq":"אֵין בְּעָיָה","tr":"эйн беая́","ru":"нет проблем"},{"he":"אל תדאג","nq":"אַל תִּדְאַג","tr":"аль тидъа́г","ru":"не волнуйся (м)"},{"he":"אל תדאגי","nq":"אַל תִּדְאֲגִי","tr":"аль тидъаги́","ru":"не волнуйся (ж)"},{"he":"אף אחד לא ענה","nq":"אַף אֶחָד לֹא עָנָה","tr":"аф эха́д ло ана́","ru":"никто не ответил"},{"he":"לא קרה כלום","nq":"לֹא קָרָה כְּלוּם","tr":"ло кара́ клум","ru":"ничего не случилось"},{"he":"הוא לא בבית","nq":"הוּא לֹא בַּבַּיִת","tr":"hу ло баба́йит","ru":"его нет дома"}],"quiz":[{"q":"«Не волнуйся» (мужчине):","opts":["אין תדאג","אל תדאג","לא דואג","אל דואג"],"a":1,"why":"Запрет = אל + будущее время."},{"q":"«Нет времени»:","opts":["לא יש זמן","אין זמן","אל זמן","לא זמן"],"a":1,"why":"«Не имеется» = אין."},{"q":"«Я не понимаю» (ж):","opts":["אני לא מבינה","אני אל מבינה","לא אני מבינה","אני אין מבינה"],"a":0,"why":"Перед глаголом — לא."},{"q":"«Никто не пришёл»:","opts":["לא אף אחד בא","אין אחד בא","אף אחד לא בא","אף אחד בא"],"a":2,"why":"Двойное отрицание: אף אחד + לא."},{"q":"«Не трогай!» (мужчине):","opts":["לא נוגע!","אל תיגע!","אל נוגע!","אין תיגע!"],"a":1,"why":"Запрет = אל + будущее: אל תיגע."},{"q":"Книжное «он не дома»:","opts":["הוא אל בבית","הוא אין בבית","הוא אינה בבית","הוא אינו בבית"],"a":3,"why":"אין + окончание: אינו (он), אינה (она)."},{"q":"«Я ничего не вижу» (м):","opts":["אני רואה כלום","אני לא רואה משהו","אני אין רואה כלום","אני לא רואה כלום"],"a":3,"why":"כלום требует לא при глаголе."}]},{"id":"present_paal","title":"Настоящее время: биньян פעל","level":"A1","text":["Глаголы строятся от корня из трёх согласных: כ-ת-ב — «писать». Корень вставляется в шаблон — биньян. Всего 7 биньянов, самый частый — פעל (паа́ль, или קל).","Настоящее время — это, по сути, причастие: у него 4 формы по роду и числу, как у прилагательного, а лицо не меняется. Поэтому местоимение обязательно: אני כותב, אתה כותב, הוא כותב.","Шаблон פעל: כּוֹתֵב (м), כּוֹתֶבֶת (ж), כּוֹתְבִים (м мн.), כּוֹתְבוֹת (ж мн.). Гласные «о — е».","Слабые корни: на ־ה — קונה (м, коне́), קונה (ж, кона́), קונים, קונות; с пустой серединой — גר, גרה (гара́ — ударение на последнем слоге; в разговоре часто говорят га́ра), גרים, גרות; с ח или ע в конце — יודע, יודעת (йода́ат)."],"table":{"head":["","כ-ת-ב писать","ק-נ-ה покупать","ג-ו-ר жить"],"rows":[["м. ед.","כּוֹתֵב","קוֹנֶה","גָּר"],["ж. ед.","כּוֹתֶבֶת","קוֹנָה","גָּרָה"],["м. мн.","כּוֹתְבִים","קוֹנִים","גָּרִים"],["ж. мн.","כּוֹתְבוֹת","קוֹנוֹת","גָּרוֹת"]]},"examples":[{"he":"אני כותבת מכתב","nq":"אֲנִי כּוֹתֶבֶת מִכְתָּב","tr":"ани́ коте́вет михта́в","ru":"я пишу письмо (ж)"},{"he":"הוא עובד בבנק","nq":"הוּא עוֹבֵד בַּבַּנְק","tr":"hу ове́д баба́нк","ru":"он работает в банке"},{"he":"הם גרים בחיפה","nq":"הֵם גָּרִים בְּחֵיפָה","tr":"hем гари́м бехе́йфа","ru":"они живут в Хайфе"},{"he":"היא קונה ירקות","nq":"הִיא קוֹנָה יְרָקוֹת","tr":"hи кона́ йерако́т","ru":"она покупает овощи"},{"he":"אנחנו לומדים עברית","nq":"אֲנַחְנוּ לוֹמְדִים עִבְרִית","tr":"ана́хну ломди́м иври́т","ru":"мы учим иврит"},{"he":"את יודעת?","nq":"אַתְּ יוֹדַעַת?","tr":"ат йода́ат?","ru":"ты (ж) знаешь?"},{"he":"הן אוכלות ארוחת ערב","nq":"הֵן אוֹכְלוֹת אֲרוּחַת עֶרֶב","tr":"hен охло́т аруха́т э́рев","ru":"они (ж) ужинают"}],"quiz":[{"q":"היא ___ (пишет)","opts":["כותב","כותבת","כותבות","כותבים"],"a":1,"why":"Она, ед. число → כותבת."},{"q":"אנחנו ___ בתל אביב (мы живём; м или смешанная группа)","opts":["גרות","גר","גרה","גרים"],"a":3,"why":"Мн. число, м.р. → גרים."},{"q":"היא ___ לחם (покупает)","opts":["קונה","קונת","קונים","קנתה"],"a":0,"why":"Корень на ־ה: ж.р. קונה (кона́)."},{"q":"את ___ עברית? (ты знаешь; ж)","opts":["יודע","ידעת","יודעים","יודעת"],"a":3,"why":"Ж.р. ед. число → יודעת (йода́ат)."},{"q":"Зачем в настоящем времени нужно местоимение?","opts":["форма не показывает лицо, только род и число","оно не нужно","только в вопросах","только для вежливости"],"a":0,"why":"כותב = пишу / пишешь / пишет — лицо видно только по местоимению."},{"q":"הם ___ בבנק (работают)","opts":["עובדת","עובד","עובדים","עובדות"],"a":2,"why":"Мн. число, м.р. → עובדים."},{"q":"Как называется самый простой биньян?","opts":["הפעיל","התפעל","פעל (קל)","פיעל"],"a":2,"why":"פעל, он же קל — «лёгкий»."},{"q":"Ж.р. от שומע (слышит):","opts":["שמעה","שומעית","שומעה","שומעת"],"a":3,"why":"С ע в конце: שומעת (шома́ат)."}]},{"id":"prepositions","title":"Предлоги: ב, ל, מ, על, עם, של","level":"A1","text":["Самые частые предлоги — из одной буквы, пишутся слитно со словом: ב — в, на (место, время, средство); ל — к, в (куда), для, кому; מ — из, от; כ — как.","Произношение: обычно бе-, ле-, ке-: בחיפה (бехе́йфа), לחיפה. מ перед большинством букв — ми-: מתל אביב; перед א, ה, ח, ע, ר — ме-: מרוסיה. С артиклем — ба-, ла-, ка- (см. урок об артикле).","Отдельные предлоги: על — на, о (про); עם — с (вместе); של — принадлежность («чей»); אצל — у (кого-то); ליד — рядом с; לפני — до, перед; אחרי — после; בלי — без.","Не переводите дословно с русского: «ехать на автобусе» — לנסוע באוטובוס; «думать о» — לחשוב על; «ждать кого-то» — לחכות ל…; «звонить кому-то» — להתקשר ל…; «бояться чего-то» — לפחד מ…"],"table":{"head":["Предлог","Значение","Пример"],"rows":[["בְּ־","в, на, при","בַּבַּיִת — дома"],["לְ־","к, в (куда), для, кому","לָעֲבוֹדָה — на работу"],["מִ־ / מֵ־","из, от","מֵהָעֲבוֹדָה — с работы"],["עַל","на, о (про)","עַל הַשֻּׁלְחָן — на столе"],["עִם","с (вместе)","עִם חָבֵר — с другом"],["שֶׁל","чей (принадлежность)","הַבַּיִת שֶׁל דָּנִי — дом Дани"],["אֵצֶל","у (кого-то)","אֵצֶל הָרוֹפֵא — у врача"],["בְּלִי","без","בְּלִי סֻכָּר — без сахара"]]},"examples":[{"he":"אני גר בתל אביב","nq":"אֲנִי גָּר בְּתֵל אָבִיב","tr":"ани́ гар бете́ль-ави́в","ru":"я живу в Тель-Авиве (м)"},{"he":"אני גרה בחיפה","nq":"אֲנִי גָּרָה בְּחֵיפָה","tr":"ани́ гара́ бехе́йфа","ru":"я живу в Хайфе (ж)"},{"he":"אני נוסעת לעבודה באוטובוס","nq":"אֲנִי נוֹסַעַת לָעֲבוֹדָה בָּאוֹטוֹבּוּס","tr":"ани́ носа́ат лаавода́ ба-о́тобус","ru":"я еду на работу на автобусе (ж)"},{"he":"הספר של דני","nq":"הַסֵּפֶר שֶׁל דָּנִי","tr":"hасе́фер шель да́ни","ru":"книга Дани"},{"he":"קפה בלי סוכר","nq":"קָפֶה בְּלִי סֻכָּר","tr":"кафе́ бли сука́р","ru":"кофе без сахара"},{"he":"אני מחכה לאוטובוס","nq":"אֲנִי מְחַכֶּה לָאוֹטוֹבּוּס","tr":"ани́ мехаке́ ла-о́тобус","ru":"я жду автобус (м)"},{"he":"הוא אצל הרופא","nq":"הוּא אֵצֶל הָרוֹפֵא","tr":"hу э́цель hарофе́","ru":"он у врача"}],"quiz":[{"q":"Как сказать «на автобусе» (ехать)?","opts":["מאוטובוס","באוטובוס","על אוטובוס","לאוטובוס"],"a":1,"why":"Транспорт — с ב: לנסוע באוטובוס."},{"q":"«Думать о…» — какой предлог? לחשוב ___","opts":["מ","ב","עם","על"],"a":3,"why":"לחשוב על — думать о."},{"q":"«Дом Дани»:","opts":["הבית של דני","הבית מדני","הבית לדני","הבית אצל דני"],"a":0,"why":"Принадлежность — של."},{"q":"«Из Иерусалима»:","opts":["בירושלים","עם ירושלים","לירושלים","מירושלים"],"a":3,"why":"«Из» = מ."},{"q":"«Кофе без сахара»:","opts":["קפה עם סוכר","קפה בלי סוכר","קפה בסוכר","קפה של סוכר"],"a":1,"why":"«Без» = בלי."},{"q":"«Он боится собак»: הוא מפחד ___כלבים","opts":["ב","ל","על","מ"],"a":3,"why":"לפחד מ… — бояться чего-то: מכלבים."},{"q":"«Я у врача» (нахожусь там):","opts":["אני אצל הרופא","אני של הרופא","אני על הרופא","אני מהרופא"],"a":0,"why":"«У кого-то» = אצל."},{"q":"«Я жду автобус»: אני מחכה ___אוטובוס","opts":["מ","את","ל","על"],"a":2,"why":"לחכות ל… — ждать кого-то/что-то: לאוטובוס."}]},{"id":"numbers","title":"Числительные: мужской и женский род","level":"A1","text":["У числительных два набора форм: для мужского и для женского рода. Странно, но с 3 до 10 мужские формы кончаются на ־ה, а женские — нет: שלושה ילדים, но שלוש ילדות.","Женские формы — самые употребительные: ими считают «просто так», называют номера телефонов, время и цены: אחת, שתיים, שלוש, ארבע…","Числительное стоит перед существительным: חמש דקות, שלושה ימים. Исключение — «один»: он стоит после: ילד אחד, ילדה אחת.","«Два» перед существительным сокращается: שני ילדים (шней), שתי ילדות (штей). 9 — תשע / תשעה, 10 — עשר / עשרה. Десятки одинаковы для обоих родов: עשרים, שלושים, ארבעים, חמישים…"],"table":{"head":["Число","Ж. р. (счёт)","М. р."],"rows":[["1","אַחַת — аха́т","אֶחָד — эха́д"],["2","שְׁתַּיִם — шта́им","שְׁנַיִם — шна́им"],["3","שָׁלוֹשׁ — шало́ш","שְׁלוֹשָׁה — шлоша́"],["4","אַרְבַּע — а́рба","אַרְבָּעָה — арбаа́"],["5","חָמֵשׁ — хаме́ш","חֲמִשָּׁה — хамиша́"],["6","שֵׁשׁ — шеш","שִׁשָּׁה — шиша́"],["7","שֶׁבַע — ше́ва","שִׁבְעָה — шивъа́"],["8","שְׁמוֹנֶה — шмо́не","שְׁמוֹנָה — шмона́"]]},"examples":[{"he":"ילד אחד","nq":"יֶלֶד אֶחָד","tr":"е́лед эха́д","ru":"один мальчик"},{"he":"שני ילדים","nq":"שְׁנֵי יְלָדִים","tr":"шней йелади́м","ru":"два мальчика"},{"he":"שתי בנות","nq":"שְׁתֵּי בָּנוֹת","tr":"штей бано́т","ru":"две девочки (дочери)"},{"he":"שלושה ימים","nq":"שְׁלוֹשָׁה יָמִים","tr":"шлоша́ ями́м","ru":"три дня"},{"he":"חמש דקות","nq":"חָמֵשׁ דַּקּוֹת","tr":"хаме́ш дако́т","ru":"пять минут"},{"he":"ארבע שנים","nq":"אַרְבַּע שָׁנִים","tr":"а́рба шани́м","ru":"четыре года"},{"he":"עשרה אנשים","nq":"עֲשָׂרָה אֲנָשִׁים","tr":"асара́ анаши́м","ru":"десять человек"}],"quiz":[{"q":"___ ילדים (три мальчика)","opts":["שלוש","שלושה","שלושים","שלושת"],"a":1,"why":"ילד — м.р. → форма с ־ה: שלושה."},{"q":"___ דקות (пять минут)","opts":["חמישה","חמישים","חמש","חמשת"],"a":2,"why":"דקה — ж.р. → חמש."},{"q":"«Одна девочка»:","opts":["ילדה אחת","אחד ילדה","ילדה אחד","אחת ילדה"],"a":0,"why":"«Один» стоит после существительного и согласуется: אחת."},{"q":"«Два мальчика»:","opts":["שניים ילדים","שני ילדים","שתי ילדים","ילדים שניים"],"a":1,"why":"Перед существительным שניים → שני."},{"q":"«Две машины» (מכונית — ж.р.):","opts":["שני מכוניות","שתי מכוניות","שתיים מכוניות","מכוניות שתיים"],"a":1,"why":"Ж.р. перед существительным → שתי."},{"q":"Какими формами считают «просто так» (раз, два, три)?","opts":["женскими: אחת, שתיים, שלוש","мужскими: אחד, שניים, שלושה","только цифрами","любыми"],"a":0,"why":"При счёте, в номерах и времени — женские формы."},{"q":"«Четыре года» (שנה — ж.р.):","opts":["ארבעה שנים","ארבעת שנים","ארבע שנים","ארבעים שנים"],"a":2,"why":"שנה — ж.р. (хотя мн. число на ־ים) → ארבע."},{"q":"Сколько будет עשרים?","opts":["2","12","20","200"],"a":2,"why":"עשרים (эсри́м) — двадцать."}]},{"id":"prep_pronouns","title":"Предлоги с местоимениями: לי, שלי, איתי…","level":"A2","text":["Предлог не соединяется с отдельным местоимением: нельзя сказать «ל אני». Вместо этого к предлогу прибавляются окончания: לי, לך, לו, לה…","Окончания почти одинаковы у всех предлогов: ־י (я), ־ך (ты: м — «-ха», ж — «-ах»), ־ו (он), ־ה (она), ־נו (мы), ־כם / ־כן (вы), ־הם / ־הן (они).","У некоторых предлогов своя основа: עם → איתי, איתך, איתו; מ → ממני, ממך, ממנו, ממנה; у על и אל перед окончанием появляется י: עליי, עליך, עליו, עלינו; אליי, אליך.","Обратите внимание: ממנו — это и «от него», и «от нас»; смысл понятен из контекста."],"table":{"head":["Кто","ל","של","עם","מ","על"],"rows":[["אני","לי — ли","שלי — шели́","איתי — ити́","ממני — миме́ни","עליי — ала́й"],["אתה","לך — леха́","שלך — шелха́","איתך — итха́","ממך — мимха́","עליך — але́ха"],["את","לך — лах","שלך — шела́х","איתך — ита́х","ממך — миме́х","עלייך — ала́йих"],["הוא","לו — ло","שלו — шело́","איתו — ито́","ממנו — миме́ну","עליו — ала́в"],["היא","לה — ла","שלה — шела́","איתה — ита́","ממנה — миме́на","עליה — але́hа"],["אנחנו","לנו — ла́ну","שלנו — шела́ну","איתנו — ита́ну","ממנו — миме́ну","עלינו — але́ну"],["אתם","לכם — лахе́м","שלכם — шелахе́м","איתכם — итхе́м","מכם — мике́м","עליכם — алейхе́м"],["הם","להם — лаhе́м","שלהם — шелаhе́м","איתם — ита́м","מהם — меhе́м","עליהם — алейhе́м"]]},"examples":[{"he":"תודה לך","nq":"תּוֹדָה לְךָ","tr":"тода́ леха́","ru":"спасибо тебе (м)"},{"he":"זה שלי","nq":"זֶה שֶׁלִּי","tr":"зе шели́","ru":"это моё"},{"he":"בוא איתי","nq":"בּוֹא אִתִּי","tr":"бо ити́","ru":"пойдём со мной (м)"},{"he":"מה איתך?","nq":"מָה אִתָּךְ?","tr":"ма ита́х?","ru":"как ты? что с тобой? (ж)"},{"he":"אני חושבת עליך","nq":"אֲנִי חוֹשֶׁבֶת עָלֶיךָ","tr":"ани́ хоше́вет але́ха","ru":"я думаю о тебе (ж → м)"},{"he":"הוא גדול ממני","nq":"הוּא גָּדוֹל מִמֶּנִּי","tr":"hу гадо́ль миме́ни","ru":"он старше (больше) меня"},{"he":"קשה לנו","nq":"קָשֶׁה לָנוּ","tr":"каше́ ла́ну","ru":"нам трудно"},{"he":"יש לכם שאלות?","nq":"יֵשׁ לָכֶם שְׁאֵלוֹת?","tr":"еш лахе́м шеэло́т?","ru":"у вас есть вопросы?"}],"quiz":[{"q":"«Со мной»:","opts":["עימני","איתו","עם אני","איתי"],"a":3,"why":"עם + я → איתי (ити́)."},{"q":"«От неё»:","opts":["מהן","ממנו","מהיא","ממנה"],"a":3,"why":"מ + она → ממנה (миме́на)."},{"q":"«О нас» (думать о нас): לחשוב ___","opts":["על אנחנו","עליו","עלינו","עליהם"],"a":2,"why":"על + мы → עלינו."},{"q":"«Твой дом» (обращаясь к женщине): הבית ___","opts":["שלכן","שלך","שלה","שלו"],"a":1,"why":"Пишется так же, как для мужчины, но читается «шела́х»."},{"q":"Что может означать ממנו?","opts":["только «от нас»","только «от него»","«от него» или «от нас»","«от них»"],"a":2,"why":"ממנו — общая форма для «он» и «мы»."},{"q":"«Скажи им» (о мужчинах): תגיד ___","opts":["להם","לו","לכם","להן"],"a":0,"why":"ל + они (м) → להם."},{"q":"«У вас есть» (группе):","opts":["יש לך","יש להם","יש לנו","יש לכם"],"a":3,"why":"ל + вы → לכם."},{"q":"«С ним»:","opts":["איתם","ממנו","איתה","איתו"],"a":3,"why":"עם + он → איתו (ито́)."}]},{"id":"et","title":"את — показатель прямого дополнения","level":"A2","text":["Если прямое дополнение определённое (с ה, имя собственное, слово с «мой», «этот» и т. п.), перед ним ставится את (эт). Оно не переводится: אני רואה את הים — я вижу море.","Если дополнение неопределённое, את не нужно: אני קונה לחם — покупаю хлеб (какой-нибудь); אני קונה את הלחם הזה — покупаю этот хлеб.","С местоимениями את превращается в אות־: אותי, אותך, אותו, אותה, אותנו, אתכם, אותם. «Я люблю тебя» = אני אוהב אותך.","Не путайте: את (эт) — показатель дополнения, и את (ат) — «ты» (ж): пишутся одинаково, звучат по-разному. И не путайте אותך (тебя) с איתך (с тобой)."],"table":{"head":["Кто","Форма","Перевод"],"rows":[["אני","אוֹתִי — оти́","меня"],["אתה / את","אוֹתְךָ / אוֹתָךְ — отха́ / ота́х","тебя"],["הוא / היא","אוֹתוֹ / אוֹתָהּ — ото́ / ота́","его / её"],["אנחנו","אוֹתָנוּ — ота́ну","нас"],["אתם / אתן","אֶתְכֶם / אֶתְכֶן — этхе́м / этхе́н","вас"],["הם / הן","אוֹתָם / אוֹתָן — ота́м / ота́н","их"]]},"examples":[{"he":"אני רואה את הים","nq":"אֲנִי רוֹאֶה אֶת הַיָּם","tr":"ани́ роэ́ эт hая́м","ru":"я вижу море (м)"},{"he":"אני קונה לחם","nq":"אֲנִי קוֹנָה לֶחֶם","tr":"ани́ кона́ ле́хем","ru":"я покупаю хлеб (ж)"},{"he":"אני אוהבת אותך","nq":"אֲנִי אוֹהֶבֶת אוֹתְךָ","tr":"ани́ оhе́вет отха́","ru":"я люблю тебя (ж → м)"},{"he":"ראית את דני?","nq":"רָאִיתָ אֶת דָּנִי?","tr":"раи́та эт да́ни?","ru":"ты (м) видел Дани?"},{"he":"אני מכיר אותו","nq":"אֲנִי מַכִּיר אוֹתוֹ","tr":"ани́ маки́р ото́","ru":"я его знаю (м)"},{"he":"אני מחפשת את המפתחות","nq":"אֲנִי מְחַפֶּשֶׂת אֶת הַמַּפְתְּחוֹת","tr":"ани́ мехапе́сет эт hамафтехо́т","ru":"я ищу ключи (ж)"},{"he":"אנחנו מזמינים אתכם","nq":"אֲנַחְנוּ מַזְמִינִים אֶתְכֶם","tr":"ана́хну мазмини́м этхе́м","ru":"мы приглашаем вас"}],"quiz":[{"q":"אני רואה ___ הבית (вижу этот дом)","opts":["את","ל","על","של"],"a":0,"why":"Определённое прямое дополнение → את."},{"q":"Где всё правильно: «покупаю хлеб» (какой-нибудь)?","opts":["את אני קונה לחם","אני את קונה לחם","אני קונה לחם","אני קונה את לחם"],"a":2,"why":"Неопределённое дополнение — без את."},{"q":"«Я люблю тебя» (мужчина — женщине):","opts":["אני אוהב לך","אני אוהב את","אני אוהב אותך","אני אוהב איתך"],"a":2,"why":"את + ты → אותך."},{"q":"«Я знаю его» (знаком с ним):","opts":["אני מכיר איתו","אני מכיר את הוא","אני מכיר לו","אני מכיר אותו"],"a":3,"why":"את + он → אותו."},{"q":"«Я видел Дани»:","opts":["ראיתי דני","ראיתי אותו דני","ראיתי לדני","ראיתי את דני"],"a":3,"why":"Имя собственное — определённое → את."},{"q":"«Мы приглашаем вас» (по норме):","opts":["אנחנו מזמינים אתכם","אנחנו מזמינים איתכם","אנחנו מזמינים לכם","אנחנו מזמינים אותכם"],"a":0,"why":"Правильно אתכם; אותכם — частая разговорная ошибка."},{"q":"Как читается את в сочетании את הספר?","opts":["от","ит","эт","ат"],"a":2,"why":"Показатель дополнения читается «эт»."},{"q":"«Она ищет их» (мужчин):","opts":["היא מחפשת להם","היא מחפשת אותם","היא מחפשת איתם","היא מחפשת אותן"],"a":1,"why":"את + они (м) → אותם."}]},{"id":"time_price","title":"Цены и время на часах","level":"A2","text":["Цены: כמה זה עולה? — сколько это стоит? Ответ: זה עולה עשרים שקל. С числами в разговоре обычно говорят שקל в единственном числе: חמישים שקל, מאה שקל. Мелочь — אגורות: חמישים אגורות = полшекеля.","Сотни и тысячи: מאה (100), מאתיים (200), שלוש מאות (300), אלף (1000), אלפיים (2000), שלושת אלפים (3000).","Время: מה השעה? — который час? Ответ — женскими числительными, потому что שעה женского рода: השעה שלוש — три часа. ועשרה — и десять минут, ורבע — и четверть, וחצי — и половина, רבע ל… — без четверти.","Внимание: שתיים וחצי — это 2:30, то есть «половина третьего». «В три часа» — בשלוש или בשעה שלוש. Часть дня добавляется в конце: שמונה בבוקר, שמונה בערב."],"table":{"head":["Иврит","Транскрипция","Перевод"],"rows":[["מָה הַשָּׁעָה?","ма hашаа́?","который час?"],["הַשָּׁעָה שָׁלוֹשׁ","hашаа́ шало́ш","три часа"],["שָׁלוֹשׁ וָחֵצִי","шало́ш вахе́ци","половина четвёртого"],["אַרְבַּע וָרֶבַע","а́рба варе́ва","четверть пятого"],["רֶבַע לְחָמֵשׁ","ре́ва лехаме́ш","без четверти пять"],["שֵׁשׁ וְעֶשְׂרִים","шеш веэсри́м","шесть двадцать"],["כַּמָּה זֶה עוֹלֶה?","ка́ма зе оле́?","сколько это стоит?"],["מֵאָה שֶׁקֶל","ме́а ше́кель","сто шекелей"]]},"examples":[{"he":"זה עולה עשרים שקל","nq":"זֶה עוֹלֶה עֶשְׂרִים שֶׁקֶל","tr":"зе оле́ эсри́м ше́кель","ru":"это стоит двадцать шекелей"},{"he":"חמישים אגורות","nq":"חֲמִשִּׁים אֲגוֹרוֹת","tr":"хамиши́м агоро́т","ru":"пятьдесят агорот"},{"he":"מאתיים שקל","nq":"מָאתַיִם שֶׁקֶל","tr":"мата́им ше́кель","ru":"двести шекелей"},{"he":"הפגישה בשמונה בבוקר","nq":"הַפְּגִישָׁה בִּשְׁמוֹנֶה בַּבֹּקֶר","tr":"hапгиша́ бишмо́не бабо́кер","ru":"встреча в восемь утра"},{"he":"נתראה בשבע וחצי","nq":"נִתְרָאֶה בְּשֶׁבַע וָחֵצִי","tr":"нитрае́ беше́ва вахе́ци","ru":"увидимся в половине восьмого"},{"he":"עכשיו רבע לעשר","nq":"עַכְשָׁו רֶבַע לְעֶשֶׂר","tr":"ахша́в ре́ва леэ́сер","ru":"сейчас без четверти десять"},{"he":"אלף שקל","nq":"אֶלֶף שֶׁקֶל","tr":"э́леф ше́кель","ru":"тысяча шекелей"}],"quiz":[{"q":"«Половина третьего» (2:30):","opts":["שניים וחצי","שלוש וחצי","שתיים וחצי","חצי שתיים"],"a":2,"why":"В иврите считают от прошедшего часа: 2 + половина. Для времени — женская форма שתיים."},{"q":"«Без четверти пять»:","opts":["ארבע ורבע","חמש ורבע","רבע לארבע","רבע לחמש"],"a":3,"why":"רבע ל… = без четверти."},{"q":"«Двести»:","opts":["שתי מאות","מאתיים","מאה שתיים","שני מאה"],"a":1,"why":"200 — особая форма מאתיים."},{"q":"Почему говорят השעה שלוש, а не שלושה?","opts":["обе формы правильны","это исключение без причины","שעה — ж.р., поэтому женские числительные","שלושה устарело"],"a":2,"why":"Время называют женскими формами."},{"q":"«Сколько это стоит?»","opts":["כמה זה עולים?","כמה זה עולה?","מה זה עולה?","איפה זה עולה?"],"a":1,"why":"כמה — сколько, עולה — стоит."},{"q":"«В восемь вечера»:","opts":["שמונה של ערב","לשמונה ערב","בשמונה בערב","בשמונה בבוקר"],"a":2,"why":"ב + час + בערב."},{"q":"«Триста»:","opts":["שלושה מאות","שלושים מאה","שלוש מאות","שלוש מאה"],"a":2,"why":"מאה — ж.р. → שלוש מאות."},{"q":"50 агорот — это…","opts":["50 шекелей","полшекеля","пять шекелей","полторы агоры"],"a":1,"why":"100 агорот = 1 шекель."}]},{"id":"present_binyanim","title":"Настоящее время: פיעל, הפעיל, התפעל, נפעל","level":"A2","text":["У каждого биньяна в настоящем времени свой узнаваемый облик. Учитесь узнавать его по приставке и гласным.","פיעל — приставка מְ־, гласные «а — е»: מְדַבֵּר (говорит), מְחַפֵּשׂ (ищет), מְבַשֵּׁל (готовит). Ж.р. на ־ת: מדברת (медабе́рет).","הפעיל — приставка מַ־ и י внутри: מַזְמִין (заказывает), מַתְחִיל (начинает), מַרְגִּישׁ (чувствует). Ж.р. на ־ה: מזמינה, מתחילה.","התפעל — приставка מִתְ־, часто возвратное значение («-ся»): מִתְלַבֵּשׁ (одевается), מִתְקַשֵּׁר (звонит). Ж.р. на ־ת: מתלבשת.","נפעל — приставка נִ־, часто значение «-ся» или пассив: נִכְנָס (входит), נִשְׁאָר (остаётся). Ж.р. на ־ת: נכנסת (нихне́сет)."],"table":{"head":["Биньян","м. ед.","ж. ед.","мн. (м / ж)"],"rows":[["פעל","כּוֹתֵב","כּוֹתֶבֶת","כּוֹתְבִים / כּוֹתְבוֹת"],["פיעל","מְדַבֵּר","מְדַבֶּרֶת","מְדַבְּרִים / מְדַבְּרוֹת"],["הפעיל","מַזְמִין","מַזְמִינָה","מַזְמִינִים / מַזְמִינוֹת"],["התפעל","מִתְלַבֵּשׁ","מִתְלַבֶּשֶׁת","מִתְלַבְּשִׁים / מִתְלַבְּשׁוֹת"],["נפעל","נִכְנָס","נִכְנֶסֶת","נִכְנָסִים / נִכְנָסוֹת"]]},"examples":[{"he":"את מדברת רוסית?","nq":"אַתְּ מְדַבֶּרֶת רוּסִית?","tr":"ат медабе́рет ру́сит?","ru":"ты (ж) говоришь по-русски?"},{"he":"אני מחפש עבודה","nq":"אֲנִי מְחַפֵּשׂ עֲבוֹדָה","tr":"ани́ мехапе́с авода́","ru":"я ищу работу (м)"},{"he":"הם מזמינים פיצה","nq":"הֵם מַזְמִינִים פִּיצָה","tr":"hем мазмини́м пи́ца","ru":"они заказывают пиццу"},{"he":"השיעור מתחיל בתשע","nq":"הַשִּׁעוּר מַתְחִיל בְּתֵשַׁע","tr":"hашиу́р матхи́ль бете́ша","ru":"урок начинается в девять"},{"he":"אני מרגישה טוב","nq":"אֲנִי מַרְגִּישָׁה טוֹב","tr":"ани́ маргиша́ тов","ru":"я хорошо себя чувствую (ж)"},{"he":"הוא מתלבש מהר","nq":"הוּא מִתְלַבֵּשׁ מַהֵר","tr":"hу митлабе́ш маhе́р","ru":"он быстро одевается"},{"he":"היא נכנסת לחדר","nq":"הִיא נִכְנֶסֶת לַחֶדֶר","tr":"hи нихне́сет лахе́дер","ru":"она входит в комнату"},{"he":"אנחנו נשארים בבית","nq":"אֲנַחְנוּ נִשְׁאָרִים בַּבַּיִת","tr":"ана́хну нишъари́м баба́йит","ru":"мы остаёмся дома"}],"quiz":[{"q":"Какой биньян: מתלבש?","opts":["התפעל","פיעל","הפעיל","נפעל"],"a":0,"why":"Приставка מִתְ־ → התפעל."},{"q":"Какой биньян: מזמין?","opts":["פיעל","התפעל","הפעיל","פעל"],"a":2,"why":"מַ־ и י внутри → הפעיל."},{"q":"Какой биньян: נכנס?","opts":["פעל","פיעל","הפעיל","נפעל"],"a":3,"why":"Приставка נִ־ в настоящем → נפעל."},{"q":"היא ___ עברית (говорит)","opts":["מדברה","מדברת","מדבר","מדברים"],"a":1,"why":"פיעל, ж.р. → ־ת: מדברת."},{"q":"היא ___ טוב (чувствует себя)","opts":["מרגישה","מרגיש","מרגישים","מרגישת"],"a":0,"why":"הפעיל, ж.р. → ־ה: מרגישה."},{"q":"השיעור ___ בשמונה (урок начинается)","opts":["תחיל","מתחיל","מתחילה","מתחילים"],"a":1,"why":"שיעור — м.р., ед. число → מתחיל."},{"q":"Какая приставка у настоящего времени התפעל?","opts":["נ־","מת־","מ־ без ת","ה־"],"a":1,"why":"התפעל в настоящем: מִתְ־ (מתלבש)."},{"q":"אנחנו ___ בבית (остаёмся; м)","opts":["נשארות","נשאר","נשארים","משארים"],"a":2,"why":"נפעל, мн. число м.р. → נשארים."}]},{"id":"infinitive_modals","title":"Инфинитив и модальные слова","level":"A2","text":["Инфинитив почти всегда начинается с ל: לכתוב (писать), לדבר (говорить), להזמין (заказать), להתלבש (одеваться), להיכנס (войти). По нему легко узнать биньян.","Модальные слова стоят в настоящем времени, согласуются с подлежащим, а за ними идёт инфинитив: אני רוצה לאכול, היא צריכה ללכת, הם יכולים לעזור.","Формы: רוצה / רוצה / רוצים / רוצות (м и ж ед. пишутся одинаково, но читаются роце́ / роца́); צריך / צריכה / צריכים / צריכות; יכול / יכולה / יכולים / יכולות.","Безличные слова — без изменения: צריך (надо), אפשר (можно), אסור (нельзя), כדאי (стоит, имеет смысл): אפשר לשבת? — можно сесть? אסור לעשן — курить нельзя."],"table":{"head":["Слово","Транскрипция","Перевод"],"rows":[["רוֹצֶה / רוֹצָה","роце́ / роца́","хочу, хочет (м / ж)"],["צָרִיךְ / צְרִיכָה","цари́х / цриха́","должен, надо (м / ж)"],["יָכוֹל / יְכוֹלָה","яхо́ль / йехола́","могу, может (м / ж)"],["אוֹהֵב / אוֹהֶבֶת","оhе́в / оhе́вет","люблю, любит (м / ж)"],["אֶפְשָׁר","эфша́р","можно"],["אָסוּר","асу́р","нельзя"],["כְּדַאי","кеда́й","стоит, имеет смысл"]]},"examples":[{"he":"אני רוצה לשתות מים","nq":"אֲנִי רוֹצָה לִשְׁתּוֹת מַיִם","tr":"ани́ роца́ лишто́т ма́им","ru":"я хочу пить (воду) (ж)"},{"he":"אני צריכה ללכת","nq":"אֲנִי צְרִיכָה לָלֶכֶת","tr":"ани́ цриха́ лале́хет","ru":"мне надо идти (ж)"},{"he":"אתה יכול לעזור לי?","nq":"אַתָּה יָכוֹל לַעֲזוֹר לִי?","tr":"ата́ яхо́ль лаазо́р ли?","ru":"ты (м) можешь мне помочь?"},{"he":"את יכולה לדבר לאט?","nq":"אַתְּ יְכוֹלָה לְדַבֵּר לְאַט?","tr":"ат йехола́ ледабе́р леа́т?","ru":"ты (ж) можешь говорить медленно?"},{"he":"אפשר לשבת פה?","nq":"אֶפְשָׁר לָשֶׁבֶת פֹּה?","tr":"эфша́р лаше́вет по?","ru":"можно здесь сесть?"},{"he":"אסור לעשן","nq":"אָסוּר לְעַשֵּׁן","tr":"асу́р леаше́н","ru":"курить нельзя"},{"he":"כדאי להזמין מקום","nq":"כְּדַאי לְהַזְמִין מָקוֹם","tr":"кеда́й леhазми́н мако́м","ru":"стоит заказать место"},{"he":"הוא אוהב לבשל","nq":"הוּא אוֹהֵב לְבַשֵּׁל","tr":"hу оhе́в леваше́ль","ru":"он любит готовить"}],"quiz":[{"q":"אני ___ ללכת (мне надо идти; ж)","opts":["צריכות","צריך","צריכים","צריכה"],"a":3,"why":"Женщина о себе → צריכה."},{"q":"Инфинитив от כותב:","opts":["לכותב","לכתב","לכתוב","כתוב"],"a":2,"why":"פעל: לכתוב (лихто́в)."},{"q":"«Можно сесть?»","opts":["כדאי לשבת?","אפשר לשבת?","אסור לשבת?","צריך לשבת?"],"a":1,"why":"«Можно» = אפשר."},{"q":"הם ___ לעזור (они хотят помочь)","opts":["לרצות","רוצה","רוצות","רוצים"],"a":3,"why":"Мн. число, м.р. → רוצים."},{"q":"«Курить нельзя»:","opts":["אסור לעשן","אסור מעשן","לא אסור לעשן","אפשר לעשן"],"a":0,"why":"אסור + инфинитив."},{"q":"Инфинитив от מתלבש:","opts":["להתלבש","למתלבש","לתלבש","להלביש"],"a":0,"why":"התפעל: להת־ (להתלבש); להלביש — «одевать кого-то»."},{"q":"Инфинитив от נכנס (входит):","opts":["לכנוס","להכניס","לנכנס","להיכנס"],"a":3,"why":"נפעל: להי־ (להיכנס); להכניס — «вносить»."},{"q":"את ___ לבוא מחר? (ты можешь; ж)","opts":["יכולות","יכול","יכולה","יכולים"],"a":2,"why":"Ж.р. ед. число → יכולה."}]},{"id":"past_paal","title":"Прошедшее время: פעל, правильные глаголы","level":"A2","text":["В прошедшем времени форма меняется по лицам: окончание показывает, кто действует. Поэтому в 1-м и 2-м лице местоимение можно опустить: כתבתי — я написал(а).","Основа פעל — כָּתַב (он писал). Окончания: ־תי (я), ־ת (ты), без окончания (он), ־ה (она), ־נו (мы), ־תם / ־תן (вы), ־ו (они).","«Я» и «они» одинаковы для мужчин и женщин: כתבתי, כתבו. «Ты» на письме тоже одинаково — כתבת, но звучит по-разному: ката́вта (м) / ката́вт (ж).","Ударение: כָּתַבְתִּי (ката́вти), כָּתַבְנוּ (ката́вну) — на предпоследнем слоге; כָּתְבָה (катва́), כָּתְבוּ (катву́) — на последнем. «Вы» в разговоре обычно произносят ката́втем."],"table":{"head":["Лицо","Форма","Транскрипция"],"rows":[["אני","כָּתַבְתִּי","ката́вти"],["אתה / את","כָּתַבְתָּ / כָּתַבְתְּ","ката́вта / ката́вт"],["הוא","כָּתַב","ката́в"],["היא","כָּתְבָה","катва́"],["אנחנו","כָּתַבְנוּ","ката́вну"],["אתם / אתן","כְּתַבְתֶּם / כְּתַבְתֶּן","ктавте́м / ктавте́н (разг. ката́втем)"],["הם / הן","כָּתְבוּ","катву́"]]},"examples":[{"he":"כתבתי מכתב","nq":"כָּתַבְתִּי מִכְתָּב","tr":"ката́вти михта́в","ru":"я написал(а) письмо"},{"he":"אתמול עבדתי עד מאוחר","nq":"אֶתְמוֹל עָבַדְתִּי עַד מְאֻחָר","tr":"этмо́ль ава́дти ад меуха́р","ru":"вчера я работал(а) допоздна"},{"he":"היא גמרה את העבודה","nq":"הִיא גָּמְרָה אֶת הָעֲבוֹדָה","tr":"hи гамра́ эт hаавода́","ru":"она закончила работу"},{"he":"למדנו עברית באולפן","nq":"לָמַדְנוּ עִבְרִית בָּאֻלְפָּן","tr":"лама́дну иври́т баульпа́н","ru":"мы учили иврит в ульпане"},{"he":"הם סגרו את החנות","nq":"הֵם סָגְרוּ אֶת הַחֲנוּת","tr":"hем сагру́ эт hахану́т","ru":"они закрыли магазин"},{"he":"שמעת?","nq":"שָׁמַעְתָּ?","tr":"шама́та?","ru":"ты (м) слышал?"},{"he":"מתי חזרת הביתה?","nq":"מָתַי חָזַרְתְּ הַבַּיְתָה?","tr":"мата́й хаза́рт hаба́йта?","ru":"когда ты (ж) вернулась домой?"}],"quiz":[{"q":"אני ___ מכתב (написал)","opts":["כתבנו","כתב","כתבתי","כתבת"],"a":2,"why":"«Я» → окончание ־תי."},{"q":"היא ___ את החנות (закрыла)","opts":["סגרת","סגרו","סגרה","סגר"],"a":2,"why":"«Она» → окончание ־ה."},{"q":"הם ___ אתמול (работали)","opts":["עבדו","עבד","עבדתם","עבדנו"],"a":0,"why":"«Они» → окончание ־ו."},{"q":"אנחנו ___ עברית (учили)","opts":["לומדים","למדנו","למדו","למדתי"],"a":1,"why":"«Мы» → окончание ־נו."},{"q":"Как отличить כתבת «ты (м)» от «ты (ж)» без огласовок?","opts":["по букве י","никак, только по произношению и контексту","по окончанию ־ה","по приставке"],"a":1,"why":"Пишется одинаково: ката́вта / ката́вт."},{"q":"Форма כתבתי подходит…","opts":["только женщине","только мужчине","и мужчине, и женщине","только для «мы»"],"a":2,"why":"В прошедшем «я» не различает род."},{"q":"את ___ הביתה? (ты вернулась)","opts":["חזרה","חזרת","חזר","חזרתי"],"a":1,"why":"«Ты» → ־ת: חזרת (хаза́рт)."},{"q":"Как читается כתבו (они писали)?","opts":["котви́м","катву́","ката́вну","катаву́"],"a":1,"why":"Ударение на последнем слоге: катву́."}]},{"id":"past_weak","title":"Прошедшее время: слабые корни","level":"A2","text":["Корни на ־ה: קנה (купил), ראה (видел), עשה (сделал), שתה (пил). В 1-м и 2-м лице ה превращается в י: קניתי, קנית, קנינו. «Она» — קנתה (канта́), «они» — קנו (кану́).","Корни с пустой серединой: קם (встал), גר (жил), שם (положил); основа короткая: קַמְתִּי (ка́мти), גַּרְתִּי (га́рти). «Она» — קמה (ка́ма), «они» — קמו (ка́му): ударение на корне. Так же בא (пришёл): בָּאתִי (ба́ти), בָּאָה (ба́а), בָּאוּ (ба́у).","Корни на א: מצא (нашёл), קרא (читал, звал): מָצָאתִי (маца́ти), קָרָאתִי (кара́ти) — א не произносится.","Глаголы с נ или י в начале (נסע, ישב, ירד) и глагол הלך в прошедшем времени изменяются как правильные: נסעתי, ישבתי, הלכתי. Их трудности — в будущем времени."],"table":{"head":["","ק-נ-ה покупать","ק-ו-ם вставать","ב-ו-א приходить"],"rows":[["אני","קָנִיתִי","קַמְתִּי","בָּאתִי"],["אתה / את","קָנִיתָ / קָנִית","קַמְתָּ / קַמְתְּ","בָּאתָ / בָּאת"],["הוא","קָנָה","קָם","בָּא"],["היא","קָנְתָה","קָמָה","בָּאָה"],["אנחנו","קָנִינוּ","קַמְנוּ","בָּאנוּ"],["הם / הן","קָנוּ","קָמוּ","בָּאוּ"]]},"examples":[{"he":"קניתי לחם","nq":"קָנִיתִי לֶחֶם","tr":"кани́ти ле́хем","ru":"я купил(а) хлеб"},{"he":"ראית את הסרט?","nq":"רָאִיתָ אֶת הַסֶּרֶט?","tr":"раи́та эт hасе́рет?","ru":"ты (м) видел фильм?"},{"he":"היא שתתה קפה","nq":"הִיא שָׁתְתָה קָפֶה","tr":"hи шатета́ кафе́","ru":"она выпила кофе"},{"he":"מה עשית אתמול?","nq":"מָה עָשִׂית אֶתְמוֹל?","tr":"ма аси́т этмо́ль?","ru":"что ты (ж) делала вчера?"},{"he":"הם באו מאוחר","nq":"הֵם בָּאוּ מְאֻחָר","tr":"hем ба́у меуха́р","ru":"они пришли поздно"},{"he":"קמתי בשש","nq":"קַמְתִּי בְּשֵׁשׁ","tr":"ка́мти беше́ш","ru":"я встал(а) в шесть"},{"he":"מצאתי את המפתח","nq":"מָצָאתִי אֶת הַמַּפְתֵּחַ","tr":"маца́ти эт hамафте́ах","ru":"я нашёл (нашла) ключ"},{"he":"נסענו לאילת","nq":"נָסַעְנוּ לְאֵילַת","tr":"наса́ну леэйла́т","ru":"мы ездили в Эйлат"}],"quiz":[{"q":"אני ___ לחם (купил)","opts":["קנתי","קנהתי","קניתי","קנית"],"a":2,"why":"Корень на ־ה: ה → י перед ־תי."},{"q":"היא ___ את הסרט (видела)","opts":["ראיתה","ראית","ראה","ראתה"],"a":3,"why":"«Она» у корней на ־ה → ־תה: ראתה."},{"q":"אנחנו ___ מאוחר (пришли)","opts":["בואנו","בינו","באנו","באו"],"a":2,"why":"בא + ־נו = באנו (ба́ну); באו — «они пришли»."},{"q":"הוא ___ בשבע (встал)","opts":["קום","קמה","קמתי","קם"],"a":3,"why":"«Он» — просто основа: קם."},{"q":"מה ___ אתמול? (что вы делали; группе)","opts":["עשינו","עשו","עשיתם","עשתם"],"a":2,"why":"«Вы» у корней на ־ה → ־יתם."},{"q":"Как читается קמה (она встала)?","opts":["кама́","куму́","ками́","ка́ма"],"a":3,"why":"У пустых корней ударение на корне: ка́ма."},{"q":"אני ___ את המפתח (нашёл)","opts":["מצאת","מצתי","מציתי","מצאתי"],"a":3,"why":"Корень на א: א сохраняется на письме: מצאתי."},{"q":"הן ___ קפה (пили)","opts":["שתו","שתות","שתינו","שתתה"],"a":0,"why":"«Они» → ־ו: שתו (шату́)."}]},{"id":"comparison","title":"Сравнение: יותר, פחות, הכי, כמו","level":"A2","text":["«Больше, более» — יותר перед прилагательным: יותר גדול — больше, יותר יקר — дороже. «Чем» — מ (слитно) или מאשר: הדירה הזאת יותר גדולה מהדירה שלנו.","«Менее» — פחות: פחות יקר — менее дорогой, то есть дешевле. «Самый» — הכי: הכי טוב — лучше всего; המסעדה הכי טובה — самый лучший ресторан (артикль только у существительного).","С местоимениями «чем» принимает окончания: ממני, ממך, ממנו…: היא יותר גבוהה ממני — она выше меня.","Равенство — כמו (как): הוא גבוה כמו אבא שלו — он высокий, как его отец. В книжном языке «наилучший» — הטוב ביותר."],"table":{"head":["Иврит","Транскрипция","Перевод"],"rows":[["יוֹתֵר גָּדוֹל","йоте́р гадо́ль","больше, крупнее"],["פָּחוֹת יָקָר","пахо́т яка́р","менее дорогой"],["הֲכִי טוֹב","hахи́ тов","лучше всего, самый хороший"],["גָּדוֹל מִ־ / מֵאֲשֶׁר","гадо́ль ми- / меаше́р","больше, чем"],["כְּמוֹ","кмо","как (сравнение)"],["הַטּוֹב בְּיוֹתֵר","hато́в бейоте́р","наилучший (книжн.)"]]},"examples":[{"he":"ירושלים יותר גדולה מתל אביב","nq":"יְרוּשָׁלַיִם יוֹתֵר גְּדוֹלָה מִתֵּל אָבִיב","tr":"йерушала́им йоте́р гдола́ мите́ль-ави́в","ru":"Иерусалим больше Тель-Авива"},{"he":"היא יותר גבוהה ממני","nq":"הִיא יוֹתֵר גְּבוֹהָה מִמֶּנִּי","tr":"hи йоте́р гвоhа́ миме́ни","ru":"она выше меня"},{"he":"זה הכי טוב","nq":"זֶה הֲכִי טוֹב","tr":"зе hахи́ тов","ru":"это лучше всего"},{"he":"המסעדה הכי טובה בעיר","nq":"הַמִּסְעָדָה הֲכִי טוֹבָה בָּעִיר","tr":"hамисъада́ hахи́ това́ баи́р","ru":"лучший ресторан в городе"},{"he":"כאן פחות יקר","nq":"כָּאן פָּחוֹת יָקָר","tr":"кан пахо́т яка́р","ru":"здесь дешевле"},{"he":"הוא מדבר כמו ישראלי","nq":"הוּא מְדַבֵּר כְּמוֹ יִשְׂרְאֵלִי","tr":"hу медабе́р кмо исраэ́ли","ru":"он говорит как израильтянин"},{"he":"אני מרגישה יותר טוב","nq":"אֲנִי מַרְגִּישָׁה יוֹתֵר טוֹב","tr":"ани́ маргиша́ йоте́р тов","ru":"я чувствую себя лучше (ж)"}],"quiz":[{"q":"«Квартира больше дома»:","opts":["הדירה גדולה יותר הבית","הדירה יותר גדולה כמו הבית","הדירה יותר גדולה מהבית","הדירה הכי גדולה מהבית"],"a":2,"why":"יותר + прилагательное + מ (чем)."},{"q":"«Самый дешёвый»:","opts":["הכי זול","פחות זול","זול כמו","יותר זול"],"a":0,"why":"«Самый» = הכי."},{"q":"«Она выше меня»:","opts":["היא יותר גבוה ממני","היא יותר גבוהה אותי","היא יותר גבוהה ממני","היא הכי גבוהה ממני"],"a":2,"why":"Прилагательное в ж.р. + ממני (чем я)."},{"q":"«Как мама»:","opts":["כמו אמא","מאמא","הכי אמא","יותר אמא"],"a":0,"why":"Равенство — כמו."},{"q":"Что значит פחות יקר?","opts":["самый дорогой","менее дорогой","такой же дорогой","более дорогой"],"a":1,"why":"פחות — «менее»."},{"q":"«Лучший ресторан в городе»:","opts":["המסעדה יותר טובה בעיר","המסעדה הכי טוב בעיר","הכי המסעדה טובה בעיר","המסעדה הכי טובה בעיר"],"a":3,"why":"הכי + прилагательное, согласованное с מסעדה (ж.р.)."},{"q":"Книжное «наилучший»:","opts":["יותר טוב","טוב מאוד","הכי טוב ביותר","הטוב ביותר"],"a":3,"why":"Книжная превосходная степень: ה… ביותר."}]},{"id":"smichut","title":"Смихут — сопряжённое сочетание","level":"A2","text":["Смихут — сочетание двух существительных, где первое «принадлежит» второму: בית ספר — школа (букв. «дом книги»), כוס מים — стакан воды. По-русски это родительный падеж или прилагательное.","Первое слово может измениться: женское ־ה → ־ת: ארוחה → ארוחת בוקר (завтрак); мн. число ־ים → ־י: ילדים → ילדי הגן (дети из садика). Окончание ־ות не меняется: שעות עבודה (рабочие часы).","Артикль ставится только перед ВТОРЫМ словом: בית הספר — школа (эта), а не «הבית ספר». Прилагательное идёт после всего сочетания и согласуется с первым словом: בית ספר חדש — новая школа (בית — м.р.).","Внутри первого слова могут меняться гласные: בַּיִת → בֵּית, שָׁנָה → שְׁנַת. Если сомневаетесь, можно сказать через של: הבית של המורה."],"table":{"head":["Слово","В смихуте","Пример"],"rows":[["בַּיִת — дом","בֵּית","בֵּית סֵפֶר — школа"],["אֲרוּחָה — трапеза","אֲרוּחַת","אֲרוּחַת בֹּקֶר — завтрак"],["חֶדֶר — комната","חֲדַר","חֲדַר שֵׁנָה — спальня"],["שָׁנָה — год","שְׁנַת","שְׁנַת לִמּוּדִים — учебный год"],["יְלָדִים — дети","יַלְדֵי","יַלְדֵי הַגַּן — дети из садика"],["כּוֹס — стакан","כּוֹס","כּוֹס מַיִם — стакан воды"],["שָׂדֶה — поле","שְׂדֵה","שְׂדֵה תְּעוּפָה — аэропорт"]]},"examples":[{"he":"בית ספר","nq":"בֵּית סֵפֶר","tr":"бейт се́фер","ru":"школа"},{"he":"בית הספר החדש","nq":"בֵּית הַסֵּפֶר הֶחָדָשׁ","tr":"бейт hасе́фер hехада́ш","ru":"новая школа (эта)"},{"he":"ארוחת ערב","nq":"אֲרוּחַת עֶרֶב","tr":"аруха́т э́рев","ru":"ужин"},{"he":"כוס קפה","nq":"כּוֹס קָפֶה","tr":"кос кафе́","ru":"чашка кофе"},{"he":"חדר שינה","nq":"חֲדַר שֵׁנָה","tr":"хада́р шена́","ru":"спальня"},{"he":"מספר טלפון","nq":"מִסְפַּר טֶלֶפוֹן","tr":"миспа́р теле́фон","ru":"номер телефона"},{"he":"שדה התעופה","nq":"שְׂדֵה הַתְּעוּפָה","tr":"сде hатеуфа́","ru":"аэропорт (этот)"},{"he":"עוגת שוקולד","nq":"עוּגַת שׁוֹקוֹלָד","tr":"уга́т шокола́д","ru":"шоколадный торт"}],"quiz":[{"q":"«Школа» (эта, определённая):","opts":["הבית ספר","בית הספר","ספר הבית","הבית הספר"],"a":1,"why":"В смихуте ה ставится только перед вторым словом."},{"q":"«Завтрак» (ארוחה + בוקר):","opts":["ארוחת בוקר","ארוחה בוקר","בוקר ארוחה","ארוחי בוקר"],"a":0,"why":"ж.р. ־ה → ־ת: ארוחת."},{"q":"«Дети соседей» (ילדים + השכנים):","opts":["הילדים השכנים","ילדי של השכנים","ילדי השכנים","ילדים השכנים"],"a":2,"why":"־ים → ־י: ילדי."},{"q":"«Новая школа»:","opts":["בית ספרים חדש","בית ספר חדש","בית ספר חדשה","בית חדש ספר"],"a":1,"why":"Прилагательное — после сочетания, согласуется с בית (м.р.)."},{"q":"Куда ставится ה в смихуте?","opts":["перед первым словом","перед обоими","перед вторым словом","никогда не ставится"],"a":2,"why":"בית הספר, ארוחת הבוקר."},{"q":"Форма смихута (ед. число) от שנה (год):","opts":["שנה","שנים","שנת","שנות"],"a":2,"why":"שנה → שנת: שנת לימודים."},{"q":"«Аэропорт»:","opts":["תעופה שדה","שדת תעופה","שדה תעופה","שדה תעופות"],"a":2,"why":"שדה (поле) + תעופה (полёт)."},{"q":"«Номер телефона»:","opts":["טלפון מספר","מספר של טלפונים","מספר טלפון","מספרת טלפון"],"a":2,"why":"Главное слово первым: מספר טלפון."}]},{"id":"past_other","title":"Прошедшее время: פיעל, הפעיל, התפעל, נפעל","level":"B1","text":["Окончания прошедшего времени во всех биньянах одни и те же: ־תי, ־ת, ־ה, ־נו, ־תם, ־ו. Меняется только основа.","פיעל: דִּבֵּר (говорил) — гласная «и» в первом слоге; без огласовок пишется с י: דיבר, דיברתי, ביקשה. הפעיל: приставка הִ־ и י: הִזְמִין (заказал, пригласил), но в 1-м и 2-м лице י исчезает: הִזְמַנְתִּי.","התפעל: приставка הִתְ־: הִתְלַבֵּשׁ (оделся), הִתְקַשְּׁרָה (она позвонила). Если корень начинается с ס, ש, צ, то ת меняется с ней местами (а после צ превращается в ט): הִסְתַּדֵּר (устроился), הִשְׁתַּמֵּשׁ (использовал), הִצְטַלֵּם (сфотографировался).","נפעל: приставка נִ־: נִכְנַס (вошёл), נִכְנַסְתִּי, נִכְנְסָה, נִכְנְסוּ."],"table":{"head":["Биньян","он","я","она","они"],"rows":[["פעל","כָּתַב","כָּתַבְתִּי","כָּתְבָה","כָּתְבוּ"],["פיעל","דִּבֵּר","דִּבַּרְתִּי","דִּבְּרָה","דִּבְּרוּ"],["הפעיל","הִזְמִין","הִזְמַנְתִּי","הִזְמִינָה","הִזְמִינוּ"],["התפעל","הִתְלַבֵּשׁ","הִתְלַבַּשְׁתִּי","הִתְלַבְּשָׁה","הִתְלַבְּשׁוּ"],["נפעל","נִכְנַס","נִכְנַסְתִּי","נִכְנְסָה","נִכְנְסוּ"]]},"examples":[{"he":"דיברתי עם המנהל","nq":"דִּבַּרְתִּי עִם הַמְּנַהֵל","tr":"диба́рти им hаменаhе́ль","ru":"я поговорил(а) с начальником"},{"he":"הזמנו מונית","nq":"הִזְמַנּוּ מוֹנִית","tr":"hизма́ну мони́т","ru":"мы заказали такси"},{"he":"הוא התחיל לעבוד","nq":"הוּא הִתְחִיל לַעֲבוֹד","tr":"hу hитхи́ль лааво́д","ru":"он начал работать"},{"he":"היא התקשרה אליי","nq":"הִיא הִתְקַשְּׁרָה אֵלַי","tr":"hи hиткашра́ эла́й","ru":"она мне позвонила"},{"he":"התלבשתי מהר","nq":"הִתְלַבַּשְׁתִּי מַהֵר","tr":"hитлаба́шти маhе́р","ru":"я быстро оделся (оделась)"},{"he":"נכנסנו לבית","nq":"נִכְנַסְנוּ לַבַּיִת","tr":"нихна́сну лаба́йит","ru":"мы вошли в дом"},{"he":"השתמשתי במחשב","nq":"הִשְׁתַּמַּשְׁתִּי בַּמַּחְשֵׁב","tr":"hиштама́шти бамахше́в","ru":"я воспользовался компьютером"},{"he":"ביקשתי עזרה","nq":"בִּקַּשְׁתִּי עֶזְרָה","tr":"бика́шти эзра́","ru":"я попросил(а) помощи"}],"quiz":[{"q":"אני ___ עם דני (поговорил)","opts":["דיבר","מדברתי","דיברתי","מדבר"],"a":2,"why":"פיעל, «я» → דיברתי."},{"q":"«Я заказал» (от להזמין):","opts":["הזמין","הזמנתי","הזמינתי","מזמנתי"],"a":1,"why":"הפעיל: в 1-м лице י исчезает — הזמנתי."},{"q":"היא ___ אליי (позвонила)","opts":["מתקשרה","התקשרתי","התקשר","התקשרה"],"a":3,"why":"התפעל, «она» → ־ה: התקשרה."},{"q":"«Он использовал» (корень ש-מ-ש, התפעל):","opts":["הישתמש","התשמש","משתמש","השתמש"],"a":3,"why":"ת приставки меняется местами с ש: הת + ש → השת־."},{"q":"אנחנו ___ לבית (вошли)","opts":["נכנסו","נכנסתי","נכנסנו","נכנסים"],"a":2,"why":"נפעל, «мы» → נכנסנו."},{"q":"Какой биньян у הצטלם (сфотографировался)?","opts":["הפעיל","התפעל","פיעל","נפעל"],"a":1,"why":"הת־ + צ → הצט־: это התפעל."},{"q":"הם ___ מונית (заказали)","opts":["הזמנו","הזמין","הזמינו","מזמינו"],"a":2,"why":"«Они» → הזמינו; הזמנו — «мы заказали»."},{"q":"Какое окончание у «я» в прошедшем времени?","opts":["приставка א־","־תי во всех биньянах","־נו","־ה"],"a":1,"why":"כתבתי, דיברתי, הזמנתי, התלבשתי, נכנסתי."}]},{"id":"future","title":"Будущее время","level":"B1","text":["Будущее время образуется приставками, а для «ты» (ж), «вы» и «они» — ещё и окончаниями: אֶ־ (я), תִּ־ (ты м; она), תִּ…־י (ты ж), יִ־ (он), נִ־ (мы), תִּ…־וּ (вы), יִ…־וּ (они).","Внимание: תכתוב — это и «ты (м) напишешь», и «она напишет». В разговоре «я» часто произносят с «и»: אני יכתוב — так говорят многие, но по норме — אכתוב.","Подсказка: будущее похоже на инфинитив без ל: לדבר → ידבר, להזמין → יזמין, להתלבש → יתלבש, להיכנס → ייכנס.","Слабые корни: на ־ה — אקנה, תקנה, יקנה, יקנו; с пустой серединой — אקום, יקום, אבוא, יבוא; с י или נ в начале — אשב, אסע; и особые: ללכת → אלך, תלך, ילך; להיות → אהיה, יהיה."],"table":{"head":["Лицо","פעל (писать)","פיעל (говорить)","הפעיל (заказать)"],"rows":[["אני","אֶכְתֹּב","אֲדַבֵּר","אַזְמִין"],["אתה / היא","תִּכְתֹּב","תְּדַבֵּר","תַּזְמִין"],["את","תִּכְתְּבִי","תְּדַבְּרִי","תַּזְמִינִי"],["הוא","יִכְתֹּב","יְדַבֵּר","יַזְמִין"],["אנחנו","נִכְתֹּב","נְדַבֵּר","נַזְמִין"],["אתם / אתן","תִּכְתְּבוּ","תְּדַבְּרוּ","תַּזְמִינוּ"],["הם / הן","יִכְתְּבוּ","יְדַבְּרוּ","יַזְמִינוּ"]]},"examples":[{"he":"אני אתקשר אליך מחר","nq":"אֲנִי אֶתְקַשֵּׁר אֵלֶיךָ מָחָר","tr":"ани́ эткаше́р эле́ха маха́р","ru":"я позвоню тебе (м) завтра"},{"he":"נדבר אחר כך","nq":"נְדַבֵּר אַחַר כָּךְ","tr":"недабе́р аха́р ках","ru":"поговорим потом"},{"he":"מה תעשי בשבת?","nq":"מָה תַּעֲשִׂי בְּשַׁבָּת?","tr":"ма тааси́ бешаба́т?","ru":"что ты (ж) будешь делать в субботу?"},{"he":"הוא יבוא בשמונה","nq":"הוּא יָבוֹא בִּשְׁמוֹנֶה","tr":"hу яво́ бишмо́не","ru":"он придёт в восемь"},{"he":"נקנה את זה מחר","nq":"נִקְנֶה אֶת זֶה מָחָר","tr":"никне́ эт зе маха́р","ru":"купим это завтра"},{"he":"אני אלך הביתה","nq":"אֲנִי אֵלֵךְ הַבַּיְתָה","tr":"ани́ эле́х hаба́йта","ru":"я пойду домой"},{"he":"יהיה בסדר","nq":"יִהְיֶה בְּסֵדֶר","tr":"иhье́ бесе́дер","ru":"всё будет хорошо"}],"quiz":[{"q":"אני ___ מחר (позвоню)","opts":["התקשרתי","אתקשר","תתקשר","יתקשר"],"a":1,"why":"«Я» → приставка א־: אתקשר."},{"q":"היא ___ מכתב (напишет)","opts":["תכתוב","אכתוב","יכתוב","תכתבי"],"a":0,"why":"«Она» → приставка ת־: תכתוב."},{"q":"את ___ בשבת? (придёшь; ж)","opts":["תבואו","תבואי","יבואו","תבוא"],"a":1,"why":"«Ты» (ж) → ת…י: תבואי."},{"q":"אנחנו ___ פיצה (закажем)","opts":["נזמינו","הזמנו","נזמין","יזמין"],"a":2,"why":"«Мы» → приставка נ־: נזמין."},{"q":"Какая форма значит и «ты (м) напишешь», и «она напишет»?","opts":["תכתוב","נכתוב","יכתוב","תכתבי"],"a":0,"why":"Для «ты» (м) и «она» форма совпадает."},{"q":"הם ___ אחר כך (поговорят)","opts":["ידברו","נדבר","תדברו","ידבר"],"a":0,"why":"«Они» → י…ו: ידברו."},{"q":"Будущее от ללכת, «я»:","opts":["הלכתי","אלך","אלוך","אלכת"],"a":1,"why":"Особая форма: אלך (эле́х)."},{"q":"«Всё будет хорошо»:","opts":["יהיה בסדר","יש בסדר","היה בסדר","להיות בסדר"],"a":0,"why":"Будущее от להיות, «он/оно»: יהיה."}]},{"id":"imperative","title":"Повелительное наклонение и просьбы","level":"B1","text":["Повелительное наклонение — это будущее время без приставки: תכתוב → כתוב!, תכתבי → כתבי!, תכתבו → כתבו! Три формы: мужчине, женщине, группе.","В разговоре вместо императива очень часто говорят просто будущее время: תשב (садись), תביא לי (принеси мне), תגידי (скажи). Это звучит мягче и естественнее. Короткие формы בוא, תן, קח, חכה используются постоянно.","Запрет — только אל + будущее время: אל תלך, אל תשכחי.","«Давай(те) сделаем…» — בוא / בואי / בואו + будущее «мы»: בואו נלך — пойдёмте!"],"table":{"head":["Значение","Мужчине","Женщине","Группе"],"rows":[["иди сюда","בּוֹא","בּוֹאִי","בּוֹאוּ"],["садись","שֵׁב","שְׁבִי","שְׁבוּ"],["дай","תֵּן","תְּנִי","תְּנוּ"],["возьми","קַח","קְחִי","קְחוּ"],["подожди","חַכֵּה","חַכִּי","חַכּוּ"],["скажи (разг.)","תַּגִּיד","תַּגִּידִי","תַּגִּידוּ"],["не забудь","אַל תִּשְׁכַּח","אַל תִּשְׁכְּחִי","אַל תִּשְׁכְּחוּ"]]},"examples":[{"he":"בוא הנה!","nq":"בּוֹא הֵנָּה!","tr":"бо hе́на!","ru":"иди сюда! (м)"},{"he":"חכי רגע","nq":"חַכִּי רֶגַע","tr":"хаки́ ре́га","ru":"подожди минутку (ж)"},{"he":"תן לי את המלח","nq":"תֵּן לִי אֶת הַמֶּלַח","tr":"тен ли эт hаме́лах","ru":"дай мне соль (м)"},{"he":"תגידי, איפה הדואר?","nq":"תַּגִּידִי, אֵיפֹה הַדֹּאַר?","tr":"таги́ди, э́йфо hадо́ар?","ru":"скажи (ж), где почта?"},{"he":"תביא לי מים, בבקשה","nq":"תָּבִיא לִי מַיִם, בְּבַקָּשָׁה","tr":"тави́ ли ма́им, бевакаша́","ru":"принеси мне воды, пожалуйста (м)"},{"he":"בואו נלך","nq":"בּוֹאוּ נֵלֵךְ","tr":"бо́у неле́х","ru":"пойдёмте!"},{"he":"אל תשכחי את המפתח","nq":"אַל תִּשְׁכְּחִי אֶת הַמַּפְתֵּחַ","tr":"аль тишкехи́ эт hамафте́ах","ru":"не забудь ключ (ж)"},{"he":"שבו, בבקשה","nq":"שְׁבוּ, בְּבַקָּשָׁה","tr":"шву, бевакаша́","ru":"садитесь, пожалуйста"}],"quiz":[{"q":"«Подожди!» (женщине)","opts":["חכי!","תחכה!","חכה!","חכו!"],"a":0,"why":"Женщине → окончание ־י: חכי."},{"q":"«Садитесь!» (группе)","opts":["שב!","שבו!","ישבו!","שבי!"],"a":1,"why":"Группе → ־ו: שבו."},{"q":"Мягкая разговорная просьба «принеси» (мужчине):","opts":["להביא","הבאתי","יביא","תביא"],"a":3,"why":"Будущее «ты» (м) вместо императива: תביא."},{"q":"«Не забудь!» (мужчине)","opts":["אין תשכח!","לא שכח!","אל שכח!","אל תשכח!"],"a":3,"why":"Запрет = אל + будущее."},{"q":"«Пойдёмте!» (группе)","opts":["לכו נלך!","בואו הולכים!","בוא נלכו!","בואו נלך!"],"a":3,"why":"בואו + будущее «мы»."},{"q":"Императив от תכתבי:","opts":["תכתבו","כתבי","כתוב","תכתוב"],"a":1,"why":"Убираем приставку ת־: כתבי."},{"q":"«Дай мне» (женщине):","opts":["תנו לי","תן לי","תני לי","תתן לי"],"a":2,"why":"Женщине: תני."}]},{"id":"possessive","title":"Притяжательные суффиксы и של","level":"B1","text":["В разговоре принадлежность обычно выражают через של: הבית שלי (мой дом), החברה שלך. Существительное при этом получает артикль: הבית שלי, а не «בית שלי».","В книжном языке и в устойчивых выражениях используют суффиксы — те же, что у предлогов: ־י, ־ך, ־ו, ־ה, ־נו, ־כם, ־הם: ביתי (мой дом), שמי (моё имя).","Некоторые слова и в разговоре чаще говорят с суффиксом: אשתי (моя жена), בעלי (мой муж), לדעתי (по-моему), בעצמי (сам, сама).","Перед суффиксом женское ־ה превращается в ־ת: משפחה → משפחתי (моя семья), דעה → דעתי. Артикль с суффиксом не ставят."],"table":{"head":["С של","С суффиксом","Перевод"],"rows":[["הַשֵּׁם שֶׁלִּי","שְׁמִי","моё имя"],["הַבַּיִת שֶׁלָּנוּ","בֵּיתֵנוּ","наш дом"],["הָאִשָּׁה שֶׁלּוֹ","אִשְׁתּוֹ","его жена"],["הַבַּעַל שֶׁלָּהּ","בַּעְלָהּ","её муж"],["הַמִּשְׁפָּחָה שֶׁלִּי","מִשְׁפַּחְתִּי","моя семья"],["הַדֵּעָה שֶׁלִּי","דַּעְתִּי (לְדַעְתִּי)","моё мнение (по-моему)"],["הַיְּלָדִים שֶׁלָּהֶם","יַלְדֵיהֶם","их дети"]]},"examples":[{"he":"שמי אנה","nq":"שְׁמִי אָנָּה","tr":"шми а́на","ru":"меня зовут Анна"},{"he":"בעלי מהנדס","nq":"בַּעְלִי מְהַנְדֵּס","tr":"баали́ меhанде́с","ru":"мой муж — инженер"},{"he":"אשתו רופאה","nq":"אִשְׁתּוֹ רוֹפְאָה","tr":"ишто́ рофъа́","ru":"его жена — врач"},{"he":"לדעתי זה רעיון טוב","nq":"לְדַעְתִּי זֶה רַעְיוֹן טוֹב","tr":"ледаати́ зе раайо́н тов","ru":"по-моему, это хорошая идея"},{"he":"הבית שלנו קטן","nq":"הַבַּיִת שֶׁלָּנוּ קָטָן","tr":"hаба́йит шела́ну ката́н","ru":"наш дом маленький"},{"he":"עשיתי את זה בעצמי","nq":"עָשִׂיתִי אֶת זֶה בְּעַצְמִי","tr":"аси́ти эт зе беацми́","ru":"я сделал(а) это сам(а)"},{"he":"המשפחה שלי גרה בחיפה","nq":"הַמִּשְׁפָּחָה שֶׁלִּי גָּרָה בְּחֵיפָה","tr":"hамишпаха́ шели́ гара́ бехе́йфа","ru":"моя семья живёт в Хайфе"}],"quiz":[{"q":"«Мой дом» (разговорно):","opts":["הבית שלי","הבית לי","שלי בית","הבית של אני"],"a":0,"why":"Существительное с של получает артикль."},{"q":"Что значит אשתי?","opts":["его жена","твоя жена","женщины","моя жена"],"a":3,"why":"אישה + ־י → אשתי."},{"q":"«Меня зовут Дани» (с суффиксом):","opts":["שמך דני","שמו דני","שמנו דני","שמי דני"],"a":3,"why":"שם + ־י → שמי."},{"q":"«По-моему»:","opts":["לדעתו","של דעתי","לדעתי","בדעה שלי"],"a":2,"why":"Устойчивое выражение לדעתי."},{"q":"«Моя семья» с суффиксом:","opts":["משפחתנו","משפחהי","משפחתו","משפחתי"],"a":3,"why":"־ה → ־ת перед суффиксом: משפחתי."},{"q":"«Наша квартира»:","opts":["שלנו הדירה","הדירה לנו","הדירה שלנו","הדירה של אנחנו"],"a":2,"why":"Артикль + существительное + של."},{"q":"«Её муж»:","opts":["בעלו","בעלה","בעלי","בעליה"],"a":1,"why":"בעל + ־ה (она) → בעלה."}]},{"id":"clauses","title":"Придаточные: ש, כי, אם, כש","level":"B1","text":["ש (ше-) — универсальный союз: «что» и «который». Пишется слитно со следующим словом: אני יודע שהוא בבית — я знаю, что он дома; האיש שגר פה — человек, который живёт здесь.","В значении «который» ש не меняется по роду и числу: הספר שקניתי, הבחורה שראיתי, האנשים שעובדים פה.","כי — «потому что»: לא באתי כי הייתי חולה. אם — «если», а также «ли»: אם יהיה זמן, אבוא; אני לא יודע אם הוא יבוא — не знаю, придёт ли он.","כש (кше-) — «когда» в утверждении, не в вопросе: כשהייתי ילדה… — когда я была девочкой… Вопрос «когда?» — מתי.","Полезные союзы: לפני ש… — до того как, אחרי ש… — после того как, למרות ש… — хотя, несмотря на то что, כדי + инфинитив — чтобы: באתי כדי לעזור."],"table":{"head":["Союз","Значение","Пример"],"rows":[["שֶׁ־","что, который","אֲנִי חוֹשֵׁב שֶׁזֶּה טוֹב"],["כִּי","потому что","לֹא בָּאתִי כִּי הָיִיתִי חוֹלֶה"],["אִם","если; ли","אִם תִּרְצֶה, נֵלֵךְ"],["כְּשֶׁ־","когда (не вопрос)","כְּשֶׁאֲנִי עָיֵף, אֲנִי שׁוֹתֶה קָפֶה"],["לִפְנֵי שֶׁ־ / אַחֲרֵי שֶׁ־","до того как / после того как","אַחֲרֵי שֶׁאָכַלְנוּ, יָצָאנוּ"],["כְּדֵי לְ־","чтобы (+ инфинитив)","בָּאתִי כְּדֵי לַעֲזוֹר"],["לַמְרוֹת שֶׁ־","хотя, несмотря на то что","לַמְרוֹת שֶׁיָּרַד גֶּשֶׁם, יָצָאנוּ"]]},"examples":[{"he":"אני חושבת שהוא צודק","nq":"אֲנִי חוֹשֶׁבֶת שֶׁהוּא צוֹדֵק","tr":"ани́ хоше́вет шеhу́ цоде́к","ru":"я думаю, что он прав (ж)"},{"he":"האיש שגר לידנו","nq":"הָאִישׁ שֶׁגָּר לְיָדֵנוּ","tr":"hаи́ш шега́р леяде́ну","ru":"человек, который живёт рядом с нами"},{"he":"לא באתי כי הייתי חולה","nq":"לֹא בָּאתִי כִּי הָיִיתִי חוֹלֶה","tr":"ло ба́ти ки hаи́ти холе́","ru":"я не пришёл, потому что был болен (м)"},{"he":"אם תרצי, נלך לים","nq":"אִם תִּרְצִי, נֵלֵךְ לַיָּם","tr":"им тирци́, неле́х лая́м","ru":"если хочешь (ж), пойдём к морю"},{"he":"כשהייתי ילדה, גרתי במוסקבה","nq":"כְּשֶׁהָיִיתִי יַלְדָּה, גַּרְתִּי בְּמוֹסְקְבָה","tr":"кшеhаи́ти ялда́, га́рти бемо́сква","ru":"когда я была девочкой, я жила в Москве"},{"he":"אני לא יודע אם הוא יבוא","nq":"אֲנִי לֹא יוֹדֵעַ אִם הוּא יָבוֹא","tr":"ани́ ло йоде́а им hу яво́","ru":"я не знаю, придёт ли он (м)"},{"he":"באתי כדי לעזור","nq":"בָּאתִי כְּדֵי לַעֲזוֹר","tr":"ба́ти кдей лаазо́р","ru":"я пришёл (пришла), чтобы помочь"}],"quiz":[{"q":"«Я знаю, что ты прав» (м):","opts":["אני יודע כשאתה צודק","אני יודע אם אתה צודק","אני יודע מה אתה צודק","אני יודע שאתה צודק"],"a":3,"why":"«Что» как союз = ש."},{"q":"«Дом, который я купил»:","opts":["הבית שקניתי","הבית כשקניתי","הבית איזה קניתי","הבית מה קניתי"],"a":0,"why":"«Который» = ש, слитно."},{"q":"«Когда я был молод…» (не вопрос):","opts":["אם הייתי צעיר","מתי הייתי צעיר","כשהייתי צעיר","כי הייתי צעיר"],"a":2,"why":"«Когда» в утверждении = כש."},{"q":"לא באתי ___ הייתי עייף (не пришёл, потому что устал)","opts":["ש","אם","כי","כש"],"a":2,"why":"«Потому что» = כי."},{"q":"אני לא יודע ___ הוא יבוא (не знаю, придёт ли он)","opts":["אם","כש","ש","כי"],"a":0,"why":"«Ли» = אם."},{"q":"באתי ___ לעזור (пришёл, чтобы помочь)","opts":["אם","ש","כש","כדי"],"a":3,"why":"«Чтобы» + инфинитив = כדי."},{"q":"«Девушка, которая работает здесь»:","opts":["הבחורה שעובדת פה","הבחורה שעובד פה","הבחורה כשעובדת פה","הבחורה שעובדים פה"],"a":0,"why":"ש + глагол, согласованный с בחורה (ж.р.)."},{"q":"Как пишется ש в предложении?","opts":["слитно со следующим словом","отдельно","только с артиклем","через дефис"],"a":0,"why":"שהוא, שקניתי, שגר — всегда слитно."}]},{"id":"conditionals","title":"Условные предложения","level":"B1","text":["Реальное условие: אם + будущее время, главная часть — будущее или просьба: אם יהיה גשם, נישאר בבית — если будет дождь, останемся дома. Как и в русском, после אם ставят будущее.","Нереальное условие («если бы…»): в обеих частях — היה + причастие (форма настоящего времени): אם הייתי יודע, הייתי בא — если бы я знал, я бы пришёл. Сочетание «הייתי + причастие» = русское «бы».","Обе части согласуются с подлежащим: היא הייתה באה, הם היו עוזרים. В книжном языке вместо אם — לו или אילו: לו ידעתי…","Вежливое «хотел бы» — тоже с «бы»: הייתי רוצה להזמין שולחן — я хотел бы заказать столик. «Иначе» — אחרת: תמהר, אחרת נאחר."],"table":{"head":["Тип","Схема","Пример"],"rows":[["реальное","אִם + будущее → будущее","אִם תָּבוֹא, נְדַבֵּר"],["нереальное","אִם הָיִיתִי + причастие → הָיִיתִי + причастие","אִם הָיִיתִי יוֹדֵעַ, הָיִיתִי בָּא"],["книжное","לוּ / אִלּוּ + прошедшее","לוּ יָדַעְתִּי, הָיִיתִי בָּא"],["вежливое","הָיִיתִי + причастие","הָיִיתִי רוֹצֶה קָפֶה"]]},"examples":[{"he":"אם יהיה גשם, נישאר בבית","nq":"אִם יִהְיֶה גֶּשֶׁם, נִשָּׁאֵר בַּבַּיִת","tr":"им иhье́ ге́шем, нишаэ́р баба́йит","ru":"если будет дождь, останемся дома"},{"he":"אם תצטרכי עזרה, תתקשרי","nq":"אִם תִּצְטָרְכִי עֶזְרָה, תִּתְקַשְּׁרִי","tr":"им тицтархи́ эзра́, титкашри́","ru":"если тебе (ж) понадобится помощь, позвони"},{"he":"אם הייתי יודעת, הייתי באה","nq":"אִם הָיִיתִי יוֹדַעַת, הָיִיתִי בָּאָה","tr":"им hаи́ти йода́ат, hаи́ти баа́","ru":"если бы я знала, я бы пришла"},{"he":"הייתי רוצה להזמין שולחן","nq":"הָיִיתִי רוֹצֶה לְהַזְמִין שֻׁלְחָן","tr":"hаи́ти роце́ леhазми́н шульха́н","ru":"я хотел бы заказать столик (м)"},{"he":"הייתי רוצה לשאול משהו","nq":"הָיִיתִי רוֹצָה לִשְׁאוֹל מַשֶּׁהוּ","tr":"hаи́ти роца́ лишъо́ль ма́шеhу","ru":"я хотела бы кое-что спросить (ж)"},{"he":"אם לא תמהר, תפספס את האוטובוס","nq":"אִם לֹא תְּמַהֵר, תְּפַסְפֵס אֶת הָאוֹטוֹבּוּס","tr":"им ло темаhе́р, тефасфе́с эт hао́тобус","ru":"если не поторопишься (м), пропустишь автобус"}],"quiz":[{"q":"«Если бы я знал…» (разговорно):","opts":["אם הייתי יודע","אם יודע","אם אני ידעתי היה","אם אדע"],"a":0,"why":"Нереальное условие: היה + причастие."},{"q":"«Я бы пришла»:","opts":["הייתי בא","באתי","אבוא","הייתי באה"],"a":3,"why":"הייתי + причастие ж.р.: באה (баа́)."},{"q":"אם ___ זמן, אבוא (если будет время, приду)","opts":["יהיה","הייתה","יש היה","היה"],"a":0,"why":"Реальное условие: אם + будущее; זמן — м.р. → יהיה."},{"q":"«Я хотел бы кофе» (вежливо):","opts":["אני היה רוצה קפה","הייתי רוצה קפה","אני ארוצה קפה","רציתי היה קפה"],"a":1,"why":"Вежливое «бы»: הייתי רוצה."},{"q":"«Они бы помогли»:","opts":["הם יעזרו היו","הם היו עזרו","הם היה עוזרים","הם היו עוזרים"],"a":3,"why":"היו + причастие мн. числа."},{"q":"Книжные союзы нереального условия:","opts":["כש / כי","אחרת / לכן","כדי / למרות","לו / אילו"],"a":3,"why":"לו ידעתי… = если бы я знал…"},{"q":"תמהר, ___ נאחר (поторопись, иначе опоздаем)","opts":["אם","כי","אחרת","לכן"],"a":2,"why":"«Иначе» = אחרת."}]},{"id":"passive","title":"Пассив: נפעל, פועל, הופעל","level":"B1","text":["У активных биньянов есть пассивные пары: פעל → נפעל, פיעל → פועל, הפעיל → הופעל. Пассив часто встречается в объявлениях, новостях и на работе.","פועל — гласная «у»: ביטל (отменил) → בוטל (был отменён), תיקן (починил) → תוקן. Настоящее время — с מְ־: מבוטל (отменён), מסודר (упорядочен, аккуратный).","הופעל — приставка הוּ־ (в настоящем מוּ־): הזמין (пригласил) → הוזמן (был приглашён), מוזמן (приглашён). Сюда же מוכן (готов).","נפעל как пассив к פעל: נבנה (был построен), נכתב (был написан). Деятеля вводят словами על ידי: הבית נבנה על ידי חברה גדולה. Но в разговоре чаще говорят безлично — глаголом во мн. числе без подлежащего: סגרו את הכביש — дорогу закрыли; אומרים ש… — говорят, что…"],"table":{"head":["Актив","Пассив","Перевод"],"rows":[["בָּנָה (פעל)","נִבְנָה (נפעל)","построил → был построен"],["כָּתַב (פעל)","נִכְתַּב (נפעל)","написал → был написан"],["בִּטֵּל (פיעל)","בֻּטַּל (פועל)","отменил → был отменён"],["תִּקֵּן (פיעל)","תֻּקַּן (פועל)","починил → был починен"],["הִזְמִין (הפעיל)","הֻזְמַן (הופעל)","пригласил → был приглашён"],["הִכְנִיס (הפעיל)","הֻכְנַס (הופעל)","внёс → был внесён"]]},"examples":[{"he":"הטיסה בוטלה","nq":"הַטִּיסָה בֻּטְּלָה","tr":"hатиса́ бутла́","ru":"рейс отменён"},{"he":"המעלית תוקנה אתמול","nq":"הַמַּעֲלִית תֻּקְּנָה אֶתְמוֹל","tr":"hамаали́т тукна́ этмо́ль","ru":"лифт починили вчера"},{"he":"הבניין נבנה בשנה שעברה","nq":"הַבִּנְיָן נִבְנָה בַּשָּׁנָה שֶׁעָבְרָה","tr":"hабинья́н нивна́ башана́ шеавра́","ru":"здание построили в прошлом году"},{"he":"אתם מוזמנים!","nq":"אַתֶּם מֻזְמָנִים!","tr":"ате́м музмани́м!","ru":"вы приглашены!"},{"he":"הכול מוכן","nq":"הַכֹּל מוּכָן","tr":"hако́ль муха́н","ru":"всё готово"},{"he":"החדר מסודר","nq":"הַחֶדֶר מְסֻדָּר","tr":"hахе́дер месуда́р","ru":"комната прибрана"},{"he":"סגרו את הכביש","nq":"סָגְרוּ אֶת הַכְּבִישׁ","tr":"сагру́ эт hакви́ш","ru":"дорогу закрыли"},{"he":"הספר נכתב ברוסית","nq":"הַסֵּפֶר נִכְתַּב בְּרוּסִית","tr":"hасе́фер нихта́в беру́сит","ru":"книга написана по-русски"}],"quiz":[{"q":"Пассив от ביטל (отменил):","opts":["בוטל","נבטל","מבטל","הובטל"],"a":0,"why":"פיעל → פועל: בוטל."},{"q":"Пассив от הזמין (пригласил):","opts":["מזמין","הוזמן","התזמן","נזמן"],"a":1,"why":"הפעיל → הופעל: הוזמן."},{"q":"«Здание было построено»:","opts":["הבניין הובנה","הבניין בונה","הבניין בנה","הבניין נבנה"],"a":3,"why":"פעל (בנה) → נפעל: נבנה."},{"q":"Как чаще всего говорят в разговоре «дорогу закрыли»?","opts":["הכביש סגר","הכביש סוגר","סגרו את הכביש","הכביש סוגרה"],"a":2,"why":"Безлично: глагол во мн. числе без подлежащего."},{"q":"«Вы приглашены»:","opts":["אתם הזמנתם","אתם זמנים","אתם מוזמנים","אתם מזמינים"],"a":2,"why":"Настоящее время הופעל: מוזמנים."},{"q":"Как называется пассив к פיעל?","opts":["התפעל","נפעל","הופעל","פועל"],"a":3,"why":"פיעל → פועל (пуаль)."},{"q":"Как вводится деятель в пассиве («кем»)?","opts":["של","על ידי","בשביל","עם"],"a":1,"why":"הבית נבנה על ידי חברה — построен компанией."},{"q":"«Рейс отменён»:","opts":["הטיסה בוטלה","הטיסה מבטלת","הטיסה בוטל","הטיסה ביטלה"],"a":0,"why":"טיסה — ж.р. → בוטלה."}]},{"id":"verbal_nouns","title":"Отглагольные существительные (שם פעולה)","level":"B1","text":["От каждого биньяна образуется существительное, которое называет действие: как русское «писать → написание», «курить → курение». Таких слов много в объявлениях, документах и на работе.","Шаблоны: פעל → כתיבה (написание), נסיעה (поездка), יציאה (выход); פיעל → דיבור (речь), תיקון (ремонт), ביטול (отмена), עישון (курение); הפעיל → הזמנה (заказ, приглашение), התחלה (начало); התפעל → התנהגות (поведение), התקשרות (связь).","Род: слова на ־ה и ־ות — женского рода (נסיעה טובה, התנהגות יפה), на ־וּ־ (דיבור, תיקון) — мужского.","У נפעל есть свой шаблон (הישארות — пребывание, היעלמות — исчезновение), но часто берут слово от פעל: להיכנס (войти) — כניסה (вход)."],"table":{"head":["Биньян","Глагол","Существительное"],"rows":[["פעל","לִנְסוֹעַ — ехать","נְסִיעָה — поездка"],["פעל","לִכְתּוֹב — писать","כְּתִיבָה — написание"],["פיעל","לְתַקֵּן — чинить","תִּקּוּן — ремонт"],["פיעל","לְבַטֵּל — отменять","בִּטּוּל — отмена"],["הפעיל","לְהַזְמִין — заказывать","הַזְמָנָה — заказ"],["הפעיל","לְהַתְחִיל — начинать","הַתְחָלָה — начало"],["התפעל","לְהִתְנַהֵג — вести себя","הִתְנַהֲגוּת — поведение"],["נפעל → פעל","לְהִכָּנֵס — входить","כְּנִיסָה — вход"]]},"examples":[{"he":"נסיעה טובה!","nq":"נְסִיעָה טוֹבָה!","tr":"несиа́ това́!","ru":"счастливого пути!"},{"he":"העישון אסור","nq":"הָעִשּׁוּן אָסוּר","tr":"hаишу́н асу́р","ru":"курение запрещено"},{"he":"יש לי הזמנה על שם כהן","nq":"יֵשׁ לִי הַזְמָנָה עַל שֵׁם כֹּהֵן","tr":"еш ли hазмана́ аль шем коhе́н","ru":"у меня заказ на фамилию Коэн"},{"he":"הכניסה חופשית","nq":"הַכְּנִיסָה חָפְשִׁית","tr":"hакниса́ хофши́т","ru":"вход свободный"},{"he":"התיקון לוקח שבוע","nq":"הַתִּקּוּן לוֹקֵחַ שָׁבוּעַ","tr":"hатику́н локе́ах шаву́а","ru":"ремонт занимает неделю"},{"he":"זאת רק ההתחלה","nq":"זֹאת רַק הַהַתְחָלָה","tr":"зот рак hаhатхала́","ru":"это только начало"},{"he":"איפה היציאה?","nq":"אֵיפֹה הַיְּצִיאָה?","tr":"э́йфо hайециа́?","ru":"где выход?"}],"quiz":[{"q":"Существительное от לבטל (отменять):","opts":["התבטלות","בטילה","ביטול","הבטלה"],"a":2,"why":"פיעל → шаблон ־וּ־: ביטול."},{"q":"Существительное от להזמין (заказывать):","opts":["הזמן","הזמנה","מזמין","זמינות"],"a":1,"why":"הפעיל → шаблон הַ־…ָה: הזמנה."},{"q":"Существительное от לנסוע (ехать):","opts":["ניסוע","נוסע","נסיעה","הנסעה"],"a":2,"why":"פעל → шаблон ־יעה: נסיעה; נוסע — «пассажир»."},{"q":"Какого рода התנהגות (поведение)?","opts":["мужского","обоих","женского","среднего"],"a":2,"why":"Окончание ־ות → женский род."},{"q":"«Вход свободный»:","opts":["הכניסה חופשית","הכניסה חופשי","להיכנס חופשית","הנכנס חופשי"],"a":0,"why":"כניסה — ж.р. → חופשית."},{"q":"Что значит תיקון?","opts":["поездка","ремонт, исправление","отмена","заказ"],"a":1,"why":"От לתקן — чинить, исправлять."},{"q":"Существительное от להתחיל (начинать):","opts":["תחלוה","מתחיל","התחלה","התחילות"],"a":2,"why":"הפעיל → התחלה (hатхала́)."}]},{"id":"mistakes","title":"Типичные ошибки русскоязычных","level":"B1","text":["Род в обращении: женщине — את и женские формы: את רוצה (ат роца́), את יכולה. Самой о себе — тоже женские формы: אני רוצה (роца́), אני צריכה, אני יכולה.","Артикль и את: «мой дом» — הבית שלי (с ה!); «я вижу дом» (этот) — אני רואה את הבית (с את!).","Кальки с русского: «мне холодно» — קר לי (а не «אני קר» — это «я холодный»); «мне 60 лет» — אני בן שישים / אני בת שישים; «у меня есть» — יש לי (а не «אני יש»).","Предлоги управления не совпадают с русскими: לחכות ל… (ждать кого-то), לעזור ל… (помогать кому-то), לשאול את… (спрашивать кого-то), לנסוע ב… (ехать на транспорте)."],"table":{"head":["Ошибка","Правильно","Перевод"],"rows":[["אֲנִי קַר","קַר לִי","мне холодно"],["אֲנִי רוֹאֶה הַבַּיִת","אֲנִי רוֹאֶה אֶת הַבַּיִת","я вижу дом"],["בַּיִת שֶׁלִּי","הַבַּיִת שֶׁלִּי","мой дом"],["אֲנִי יֵשׁ מְכוֹנִית","יֵשׁ לִי מְכוֹנִית","у меня есть машина"],["אֲנִי מְחַכֶּה אוֹתְךָ","אֲנִי מְחַכֶּה לְךָ","я жду тебя"],["נוֹסֵעַ עַל אוֹטוֹבּוּס","נוֹסֵעַ בְּאוֹטוֹבּוּס","еду на автобусе"],["יֵשׁ לִי שִׁשִּׁים שָׁנָה","אֲנִי בֶּן שִׁשִּׁים / בַּת שִׁשִּׁים","мне шестьдесят лет"],["שׁוֹאֵל לְדָנִי","שׁוֹאֵל אֶת דָּנִי","спрашиваю Дани"]]},"examples":[{"he":"קר לי","nq":"קַר לִי","tr":"кар ли","ru":"мне холодно"},{"he":"משעמם לי","nq":"מְשַׁעֲמֵם לִי","tr":"мешааме́м ли","ru":"мне скучно"},{"he":"אני בת שישים וחמש","nq":"אֲנִי בַּת שִׁשִּׁים וְחָמֵשׁ","tr":"ани́ бат шиши́м вехаме́ш","ru":"мне 65 лет (ж)"},{"he":"שאלתי את המורה","nq":"שָׁאַלְתִּי אֶת הַמּוֹרֶה","tr":"шаа́льти эт hаморе́","ru":"я спросил(а) учителя"},{"he":"תעזור לי, בבקשה","nq":"תַּעֲזוֹר לִי, בְּבַקָּשָׁה","tr":"таазо́р ли, бевакаша́","ru":"помоги мне, пожалуйста (м)"},{"he":"אני מחכה לך","nq":"אֲנִי מְחַכָּה לְךָ","tr":"ани́ мехака́ леха́","ru":"я жду тебя (ж → м)"},{"he":"את רוצה קפה?","nq":"אַתְּ רוֹצָה קָפֶה?","tr":"ат роца́ кафе́?","ru":"ты (ж) хочешь кофе?"},{"he":"זה מוצא חן בעיניי","nq":"זֶה מוֹצֵא חֵן בְּעֵינַי","tr":"зе моце́ хен беэйна́й","ru":"мне это нравится"}],"quiz":[{"q":"«Мне холодно»:","opts":["אני קר","קר לי","אני קרה","יש לי קר"],"a":1,"why":"Состояние выражается безлично: קר לי."},{"q":"«Мне 70 лет» (женщина):","opts":["לי שבעים שנה","אני שבעים שנים","אני בת שבעים","יש לי שבעים שנה"],"a":2,"why":"Возраст: אני בן / בת + число."},{"q":"«Я жду автобус»:","opts":["אני מחכה לאוטובוס","אני מחכה את האוטובוס","אני מחכה אוטובוס על","אני מחכה באוטובוס"],"a":0,"why":"לחכות ל…; באוטובוס — «в автобусе»."},{"q":"«Я вижу этот дом»:","opts":["אני רואה הבית","אני רואה את הבית","אני רואה לבית","אני רואה בית ה"],"a":1,"why":"Определённое прямое дополнение требует את."},{"q":"«Мне это нравится»:","opts":["לי מוצא חן זה","אני מוצא חן זה","זה מוצא חן לי","זה מוצא חן בעיניי"],"a":3,"why":"Устойчивое выражение: מוצא חן בעיני…"},{"q":"Женщине: «ты хочешь?»","opts":["את רוצה?","אתם רוצה?","אתה רוצה?","את רוצות?"],"a":0,"why":"Женщине — את + רוצה (роца́)."},{"q":"«Помоги мне» (мужчине, разговорно):","opts":["תעזור אותי","תעזור ממני","תעזור איתי","תעזור לי"],"a":3,"why":"לעזור ל… — помогать кому-то."},{"q":"«Я спросил Дани»:","opts":["שאלתי על דני","שאלתי את דני","שאלתי לדני","שאלתי מדני"],"a":1,"why":"לשאול את… — спрашивать кого-то; על — «о ком-то»."}]}]);
